export const KB = [{"t":"physics","f":"Cannon-es uses gravity of 9.82 meters per second squared as the standard Earth gravity value"},{"t":"physics","f":"Cannon Box shape uses half-extents: a 1x1x1 Three.js BoxGeometry corresponds to a Cannon Box(0.5, 0.5, 0.5)"},{"t":"physics","f":"Cannon physics body for a dynamic object uses mass of 1 for standard interactive rigid bodies"},{"t":"physics","f":"Physics world step uses clock.getDelta() to advance simulation by the elapsed time each frame"},{"t":"rendering","f":"Two engines run simultaneously: Cannon for physics simulation and Three.js for 3D rendering; each frame you copy Cannon body positions/quaternions to Three.js mesh positions/quaternions"},{"t":"physics","f":"cannon-es version 0.18 is the maintained fork of the original cannon.js physics library, installed via npm install cannon-es --save-dev"},{"t":"npc","f":"AI controller requires calling super::OnPossess(Pawn) as the first action in the OnPossess override to ensure downstream logic in the AI controller base class executes properly \u2014 skipping super calls causes weird behavior"},{"t":"npc","f":"AI controller uses OnPossess(APawn* Pawn) virtual void override to take control of a pawn, with a Cast to the specific NPC character class to validate the pawn type before executing AI logic"},{"t":"npc","f":"NPC character class is derived from a base character class (TFCharacter), and the AI controller is a separate class that possesses and controls the NPC pawn \u2014 separation of character definition from AI behavior"},{"t":"npc","f":"NPC roaming requires a navigation mesh (nav mesh) that defines walkable areas \u2014 the nav mesh bounds volume covers the entire map including vertical space for multi-level navigation"},{"t":"npc","f":"Roaming AI pattern: separate AI Controller (brain) from AI Character (body) \u2014 controller issues movement commands, character executes them"},{"t":"npc","f":"Simple roaming NPC behavior: on begin play trigger 'start roaming' custom event that picks a random navigable location from the nav mesh and moves the AI to it"},{"t":"npc","f":"Nav mesh bounds volume needs extra vertical height to cover stairs and multi-floor areas \u2014 expand Z-axis beyond ground level"},{"t":"npc","f":"Dialogue system uses a Queue (FIFO - first in first out) data structure to manage sentences, loading all sentences into the queue when dialogue starts and dequeuing them as the player reads through"},{"t":"npc","f":"Dialogue data is stored in a separate non-MonoBehaviour class containing a public string array for sentences and a public string for NPC name, passed into a DialogueManager to start conversations"},{"t":"npc","f":"Dialogue UI consists of a dialog box image, two text objects (NPC name + dialogue text), and a continue button, built with standard Unity UI tools"},{"t":"physics","f":"Gravity set to -9.82 in the Y direction for realistic physics simulation"},{"t":"physics","f":"Ground body uses type 'static' with geometric plane shape, rotated 90 degrees to be horizontal"},{"t":"vehicles","f":"Car body mass set to 5, positioned at (0, 6, 0) to spawn above ground"},{"t":"vehicles","f":"Cannon.js RigidVehicle class handles vehicle creation including hinge constraints for wheel steering"},{"t":"vehicles","f":"Wheels use sphere shape with angular dampening, offset downward to avoid intersection with car body"},{"t":"rendering","f":"Cannon.js debugger creates green wireframe overlay on physics objects for visualization"},{"t":"physics","f":"Animation loop updates both Cannon debugger and physics world each frame for sync"},{"t":"rendering","f":"WebGL renders graphics at target 60fps using GPU-accelerated matrix multiplication/linear algebra"},{"t":"rendering","f":"3D rendering pipeline: vertices (x,y,z points) -> primitives (triangles) -> lighting/shadows -> rasterization (3D to 2D pixel projection)"},{"t":"rendering","f":"Shaders are GPU functions that customize the rendering pipeline - vertex shaders process vertex data, fragment shaders calculate per-pixel color"},{"t":"rendering","f":"WebGL is based on OpenGL (established 1992) and runs inside HTML canvas element without external plugins"},{"t":"rendering","f":"Three.js abstracts WebGL shader writing - allows 3D graphics without hand-writing GLSL shaders"},{"t":"city","f":"Forest vegetation requires models of different heights to simulate different layers of the forest canopy"},{"t":"city","f":"For terrain vegetation, 5000-10000 tree models are used to cover a terrain surface"},{"t":"rendering","f":"Terrain texture layers stack with higher layers covering lower layers, each layer supports modifiers like height (max height, max falloff) and slope for placement control"},{"t":"rendering","f":"Rock textures should be placed using a slope modifier to automatically appear on steep terrain slopes"},{"t":"rendering","f":"Terrain grass uses 4 grass models mixed automatically via spine details tool with target density controlling frequency of each model"},{"t":"rendering","f":"Stamp-based terrain sculpting uses adjustable brush size and stamp height with 'stamp from current height' set to 1 for additive stamping"},{"t":"rendering","f":"Increasing splat map resolution and map resolution improves terrain texture detail quality"},{"t":"npc","f":"NPC crowd systems use Zone Graphs with Zone Shapes to define walkable areas, with lane profiles containing forward and backward lanes"},{"t":"npc","f":"NPC crowd agents require MassAgent component with entity config containing: agent capsule collision sync, agent movement (mass-to-actor), and agent orientation align (mass-to-actor)"},{"t":"npc","f":"Crowd NPC lane profile width set to 100 units for pedestrian paths"},{"t":"npc","f":"Crowd NPCs use 2 lanes per path - one forward, one backward - for bidirectional pedestrian flow"},{"t":"npc","f":"Mass Entity crowd system uses MassCrowd plugin (MCrow) for large-scale NPC simulation"},{"t":"npc","f":"Crowd NPC characters need capsule collider positioning - mesh placed inside capsule with correct orientation"},{"t":"npc","f":"Simple crowd NPCs can use a single looping forward walk animation as their base animation blueprint"},{"t":"rendering","f":"Terrain brush size of ~400 for coarse/large terrain features, ~200 for smaller detail passes"},{"t":"rendering","f":"Grass detail distance set to 250 units to make grass visible from further away"},{"t":"rendering","f":"Fog density of 0.0045 provides good distance obscuring while looking natural"},{"t":"rendering","f":"Fog color sampled from low horizon of skybox creates cohesive sky-to-ground fade"},{"t":"rendering","f":"Grass healthy color sampled from lighter parts of base terrain texture, dry color from darker parts"},{"t":"rendering","f":"Mass place 15000 trees on terrain for dense forest coverage"},{"t":"rendering","f":"Fog used to hide LOD pop-in and grass detail distance cutoff"},{"t":"npc","f":"AI NPC conversation system requires ~28GB download for local inference, suggesting large language model running client-side"},{"t":"npc","f":"AI NPC voice response latency is variable and noticeable \u2014 sometimes 1-3 seconds delay between player speech and NPC reply"},{"t":"npc","f":"AI NPCs maintain consistent personality traits across a conversation \u2014 a hostile NPC stays hostile, a dismissive one stays dismissive"},{"t":"npc","f":"AI NPCs can contextually respond to environment \u2014 acknowledging heat, traffic, city crowding \u2014 without scripted triggers"},{"t":"city","f":"Demo city has sidewalks wide enough for 2+ NPCs side by side, vehicle traffic on roads, and stairway geometry on sidewalks"},{"t":"npc","f":"NPCs walk along sidewalks autonomously while holding props (coffee cup) and can be approached mid-walk for conversation"},{"t":"rendering","f":"Demo world has visible boundary walls ('Matrix wall') \u2014 hard invisible collision bounds at world edge"},{"t":"vehicles","f":"Car can control angular velocity while in the air to perform flip tricks"},{"t":"rendering","f":"React Three Fiber project with cannon.js physics is 4-5 files total for a complete race track with colliders"},{"t":"rendering","f":"Use Suspense component to wrap 3D asset loading in React Three Fiber"},{"t":"rendering","f":"Environment component creates 3D background from an environment map texture file"},{"t":"rendering","f":"OrbitControls component enables mouse-controlled camera with a Target property defining look-at point"},{"t":"vehicles","f":"Cannon.js used as physics engine for car racing with colliders on trees, signs, and ramps"},{"t":"rendering","f":"All Three.js/R3F hooks must be used inside the Canvas component \u2014 scene logic goes in child components"},{"t":"physics","f":"cannon-es (fork of cannon.js) uses a World object equivalent to Three.js's Scene \u2014 two engines run simultaneously: cannon for physics simulation and Three.js for 3D rendering"},{"t":"physics","f":"Gravity is set via new CANNON.World() with gravity value 9.82 m/s\u00b2 (Earth gravity), and the world is stepped each frame using world.step(delta) where delta comes from a Three.js Clock"},{"t":"physics","f":"CANNON.Box uses half-extents: a Three.js BoxGeometry(1,1,1) maps to new CANNON.Box(0.5, 0.5, 0.5), and the body is created with mass:1 then added to the world via world.addBody()"},{"t":"physics","f":"Each frame, sync physics to visuals by copying: cubeMesh.position.set(cubeBody.position.x, cubeBody.position.y, cubeBody.position.z) and cubeMesh.quaternion.copy(cubeBody.quaternion)"},{"t":"physics","f":"Without a ground plane body in the physics world, rigid bodies with gravity will fall infinitely \u2014 a floor mesh visible in Three.js does not automatically create a physics collider"},{"t":"physics","f":"cannon-es is installed via 'npm install cannon-es --save-dev' (version 0.18.x) and is a maintained fork of the original abandoned cannon.js library"},{"t":"npc","f":"AI Controller constructor requires FObjectInitializer as a const reference parameter, matching the base AAIController constructor signature"},{"t":"npc","f":"OnPossess is a virtual void override taking an APawn* pointer, used as the entry point where the AI controller takes over a pawn"},{"t":"npc","f":"Super::OnPossess(InPawn) must be called first in the OnPossess override to ensure downstream logic in the base AAIController executes properly, preventing undefined behavior"},{"t":"npc","f":"Store a private pointer to the NPC character class (ControlledPawn) initialized as nullptr, then assign it in OnPossess using Cast<ANPCCharacter>(InPawn) to verify the pawn type"},{"t":"npc","f":"After successful cast in OnPossess, retrieve the behavior tree from the NPC using ControlledPawn->GetBehaviorTree() and store it as a const UBehaviorTree* pointer"},{"t":"npc","f":"The NPC character class is derived from a shared base character class (TFCharacter), allowing both player and NPC characters to share common functionality"},{"t":"npc","f":"AI controller header uses sections private/protected/public, includes the NPC character header for the cast, and the ControlledPawn pointer does not necessarily need a UPROPERTY macro"},{"t":"npc","f":"Nav Mesh Bounds Volume actor defines walkable area for AI navigation; toggle visibility with P key to see green overlay of navigable surfaces"},{"t":"npc","f":"AI Controller blueprint class serves as the 'brain' assigned to an AI character via the AI Controller Class property in the character's Details panel"},{"t":"npc","f":"Roaming NPC uses Get Random Reachable Point in Navigable Radius node with the controlled pawn's location as origin to pick random destinations"},{"t":"npc","f":"Get Controlled Pawn node returns a Pawn object reference; pipe its return value through Get Actor Location to obtain XYZ world coordinates as the navigation origin"},{"t":"npc","f":"Nav Mesh Bounds Volume scale of 15x15x15 via Details panel creates a large navigable cube; height must cover vertical geometry like stairs for multi-floor navigation"},{"t":"npc","f":"AI character created by duplicating BP_ThirdPersonCharacter and reassigning its AI Controller Class from default to a custom controller blueprint"},{"t":"physics","f":"2D platformer uses trap collision detection where hitting any trap triggers player death and level restart"},{"t":"physics","f":"Moving platforms are used as timed obstacles that the player must wait for before proceeding"},{"t":"npc","f":"Collectible item system uses a UI counter in the top-left corner tracking collected cherry count per level"},{"t":"physics","f":"Level transition triggers load the next scene when the player reaches the end point of a level"},{"t":"physics","f":"Unity 2D platformer uses C# scripts edited in Visual Studio Community IDE with Unity autocompletion support"},{"t":"interior","f":"Unity 6 terrain tiles are massive in scale \u2014 a single tile is large enough that a player cannot traverse it in a 10-20 minute play session, so developers should focus on one tile before expanding"},{"t":"interior","f":"Build out one terrain tile completely (layers, textures, topology) before adding neighboring tiles, because adding layers after creating multiple tiles requires manually adding layers to each tile separately"},{"t":"tps","f":"Unity 6 HDRP template project includes built-in third and first person controllers; free alternatives from Unity Technologies are available on Asset Store by searching 'third person'"},{"t":"interior","f":"Terrain painting uses two primary controls: brush size and opacity, where opacity controls the influence level (strength) of the brush stroke on terrain height"},{"t":"interior","f":"Unity Shader Graph package includes importable 'production ready shaders' samples containing pre-built textures, prefabs, and rock assets that can be used as terrain layers"},{"t":"interior","f":"In Unity 6 HDRP, use File > New Scene > Basic Outdoors to get a scene with pre-built volumetric clouds and outdoor lighting setup"},{"t":"npc","f":"A Queue<string> (FIFO collection from System.Collections namespace) is used to store dialogue sentences, allowing sequential display by loading sentences from the front of the queue as the player progresses through dialogue."},{"t":"npc","f":"Dialogue data is stored in a separate non-MonoBehaviour class marked with [System.Serializable] attribute containing a public string[] sentences array and a public string name field, allowing it to appear in the Unity Inspector for editing."},{"t":"npc","f":"The architecture uses three scripts: DialogueManager (processes queue and displays text on an empty GameObject), Dialogue (serializable data class with name + sentences), and DialogueTrigger (attached to NPC/interactable to initiate conversation)."},{"t":"npc","f":"The dialogue UI consists of a Canvas containing an Image (dialog box), two Text objects (NPC name and dialogue text), and a Continue button, all built with Unity's standard UI tools."},{"t":"npc","f":"The Queue is initialized in Start() as 'sentences = new Queue<string>()' and kept as a private variable on the DialogueManager, with sentences enqueued when a new dialogue starts and dequeued as the player clicks continue."},{"t":"physics","f":"Cannon.js world gravity is set to -9.82 in the Y direction to simulate Earth gravity"},{"t":"physics","f":"Ground body uses type 'static' with a geometric plane shape, rotated 90 degrees to be horizontal instead of vertical"},{"t":"physics","f":"Cannon.js debugger takes the Three.js scene and physics world as arguments and creates green wireframe overlays on each physics object for visualization"},{"t":"vehicles","f":"Car body is created with mass=5 and positioned at (0,6,0) above ground, then wrapped in a Cannon.js RigidVehicle class that handles vehicle-specific physics"},{"t":"vehicles","f":"Wheels are sphere shapes with 'wheel' material type, offset downward to avoid intersecting the car body, with angular dampening applied"},{"t":"vehicles","f":"RigidVehicle.addWheel() internally adds hinge constraints so wheels turn correctly; requires wheel body, position, axis, and direction parameters"},{"t":"physics","f":"Animation loop must call update on both the Cannon.js debugger and the physics world every frame to keep physics and rendering in sync"},{"t":"city","f":"Gaia world generation uses a 4-step pipeline: 1) create World Designer in Gaia Manager, 2) generate world (stamps terrain), 3) spawn biome (populates vegetation/objects), 4) create runtime (enables gameplay)"},{"t":"city","f":"Gaia separates terrain shape generation (stamp step) from biome population (spawn step), allowing terrain geometry and object placement to be independently configured"},{"t":"city","f":"Gaia uses a 'stamp' system to apply heightmap and sculpting data onto Unity terrain tiles, generating landmasses like islands from predefined or procedural templates"},{"t":"npc","f":"ConvAI NPCs in UE5 generate real-time dynamic dialogue responses to player questions using generative AI, with each NPC maintaining a distinct personality and emotional state (angry car owner, concerned worker, indifferent bystander)"},{"t":"npc","f":"ConvAI NPCs maintain contextual awareness of world events (tank hit by lightning, flipped into air) and reference them coherently in unscripted voice conversations with the player"},{"t":"npc","f":"NPCs are assigned occupational roles (construction crew supervisor, investigator, civilian driver) that constrain their dialogue priorities \u2014 e.g. construction NPC only cares about crew safety, car owner NPC fixates on vehicle damage"},{"t":"city","f":"The UE5 ConvAI demo features a drivable urban street environment with civilian vehicles, construction zones, and destructible/interactive elements like tanks subject to physics events"},{"t":"physics","f":"Physics simulation triggers narrative events: a tank asset is struck by lightning and flips into the air, colliding with a civilian car \u2014 these physics outcomes become the shared context for all NPC conversations"},{"t":"vehicles","f":"Vehicle damage from physics events (tank flipping onto a car) persists in the world and NPCs reference the specific damage state \u2014 car owner NPC expresses anger about their damaged vehicle and refuses medical help"},{"t":"npc","f":"Player initiates NPC conversations with natural speech input and NPCs respond with generated voice audio in real-time, supporting multi-turn dialogue (follow-up questions like 'are you okay' and 'do you want to go to the hospital')"},{"t":"dungeon","f":"Pseudo-random number generators use a seed value fed into a formula to produce a deterministic sequence of numbers; same seed always produces the same sequence. System time is commonly used as seed for unique results each run."},{"t":"dungeon","f":"Binding of Isaac dungeon generation: start with default starting room, randomly select one of 4 sides to place next room, pick a random room from predefined layout collection, repeat until enough rooms placed, then place boss room, then optionally scatter random elements (chests, items, special objects) inside rooms."},{"t":"dungeon","f":"Random generation uses predefined elements (pre-designed rooms, objects) assembled in random configurations. Procedural generation creates entirely original content algorithmically. These are distinct approaches despite being used interchangeably."},{"t":"dungeon","f":"Random generation requires developers to create large amounts of predefined content (room layouts, object placements) beforehand to ensure variety. Procedural generation avoids this by algorithmically creating content at runtime."},{"t":"dungeon","f":"Procedural generation of worlds (Minecraft, Terraria style) relies on computer-generated noise functions rather than predefined room stitching, enabling creation of original terrain and content the developers never manually designed."},{"t":"dungeon","f":"Destructible terrain uses a dictionary with tile coordinates as keys and tile health as values; when health reaches zero the tile is removed from the tilemap. A level manager script handles tile placement and damage requests from player controller and other damage sources."},{"t":"dungeon","f":"Base tile size is 8x8 pixels for a minimalist pixel art aesthetic, chosen specifically to reduce art production time and allow focus on technical systems."},{"t":"dungeon","f":"Cave generation uses a modular noise-based system with 'World Gen Rules' (custom resource type) that define conditions, values, and thresholds. The level manager loops through world coordinates for every rule and applies them based on conditions, enabling different caves, formations, and biomes."},{"t":"dungeon","f":"Color palette shader takes each pixel's color and shifts it to the nearest color in a predefined palette (modified Dawnbringer 32 palette from lospec.com), creating banded lighting effects as lights dim and a crunchy retro look."},{"t":"dungeon","f":"Game structure replaces conventional roguelike floors/levels/rooms with a single large procedurally generated cave system. Deeper levels spawn different features, tested via a debug teleport view."},{"t":"dungeon","f":"Traversal items include bombs (area destruction + weapon), ropes (vertical traversal + weapon), and flares (light up dark areas, inspired by Deep Rock Galactic), all interacting with the destructible tile system."},{"t":"dungeon","f":"Room placement uses spawn-then-separate: spawn randomly sized prefab rooms, detect overlaps, push overlapping rooms apart based on center-of-mass direction. Repeat until all rooms are separated. If separation fails, re-run with different initial placements."},{"t":"dungeon","f":"Rooms are prefab-based with predefined doors marked as 'necessary' (green) or 'optional' (yellow). A pathfinding algorithm connects all doors between separated rooms via corridors."},{"t":"dungeon","f":"Union-Find algorithm prevents isolated room islands: maintain sets/trees of connected nodes where each tree root is the lowest node value. When merging trees, update all nodes to the new lowest value. Continue connecting until all rooms share one set."},{"t":"dungeon","f":"Multi-floor connectivity uses stair rooms that span exactly 2 floors. Union-Find tracks which floors are connected, and stair rooms are added iteratively until all floors belong to one connected set."},{"t":"dungeon","f":"The 3D algorithm is a direct extension of a 2D prototype: same overlap-separation and pathfinding-based corridor connection, but rooms are placed in 3D space and corridors are 3D hallways."},{"t":"dungeon","f":"Algorithm order: (1) place random rooms, (2) separate overlapping rooms, (3) place stair rooms connecting floors via Union-Find, (4) connect same-floor rooms with pathfinding corridors via Union-Find until fully connected."},{"t":"dungeon","f":"Procedural generation requires constraints to prevent unplayable results \u2014 pure random output produces white noise (random blocks everywhere with no terrain contour). Constraints ensure consistent surface materials, terrain flow, and structural coherence."},{"t":"dungeon","f":"Procedural generation design principle: balance enough variants to create unique/fun experiences while mitigating generation of unplayable configurations. Even a 1% chance of unplayability means 1 in 100 players gets a broken experience."},{"t":"dungeon","f":"Spawn validation is critical: if a player spawns surrounded by impassable material (e.g., stone in Terraria) with no escape, the world is unplayable. Spawn point selection must verify traversability."},{"t":"dungeon","f":"Brute-force voxel-based occlusion approximation can provide lighting for particle/voxel systems, but requires all geometry to stay within the voxel grid bounds \u2014 out-of-bounds procedural shapes get clipped, creating visual artifacts."},{"t":"dungeon","f":"Iterated Function Systems (IFS) using randomly generated sets of affine transformations produce unpredictable shapes \u2014 bounding the output within a fixed grid is a key constraint problem when combining proc-gen geometry with grid-based rendering."},{"t":"rendering","f":"WebGL rendering pipeline: vertices (x,y,z coordinates) \u2192 connected into triangles (primitives) \u2192 light source creates shadows/depth \u2192 rasterized from 3D vector to 2D pixel projection"},{"t":"rendering","f":"Shaders are functions that customize the rendering pipeline, written in OpenGL ES Shading Language (not JavaScript), processing vertex or fragment data on the GPU to calculate pixel render data"},{"t":"physics","f":"Rendering at 60fps requires massive linear algebra/matrix multiplication operations that exceed CPU capacity alone, requiring GPU distribution of calculations"},{"t":"rendering","f":"WebGL is based on OpenGL (established 1992), runs hardware-accelerated graphics on client GPU inside an HTML canvas element \u2014 initialized by getting canvas element then calling getWebGLContext()"},{"t":"rendering","f":"3D geometry is built from vertices connected into triangle primitives; rasterization converts these 3D triangles into 2D pixel projections for screen display"},{"t":"rendering","f":"Three.js and Spline are abstraction layers over WebGL that eliminate need to write raw shaders by hand for 3D web experiences"},{"t":"fps","f":"Multiplayer Three.js app architecture: front-end creates player mesh, adds to local scene, then notifies backend; backend broadcasts new player parameters to all other connected front-ends so each client adds remote players to their own scene"},{"t":"fps","f":"Player movement on front-end is handled locally using WASD or arrow keys before any network sync occurs; each client owns and controls only its own player object in the Three.js scene"},{"t":"fps","f":"Remote players are instantiated on each client by receiving parameter sets from the backend and calling the same constructor (e.g. new Hamburger with synced parameters) then adding the result to the local Three.js scene"},{"t":"fps","f":"Position the player's gun on screen so the player can see where they are shooting without needing separate crosshair UI \u2014 gun placement itself should indicate aim direction"},{"t":"fps","f":"Default FPS movement without game feel additions results in a flat glide forward feeling \u2014 camera bob, head bob, and movement sway are necessary to give the player the sensation of having legs"},{"t":"fps","f":"FPS level design should utilize full 3D vertical space rather than flat 2D layouts \u2014 a skybox alone does not make a map three-dimensional if the playable geometry is flat"},{"t":"shooting","f":"Four standard FPS weapon archetypes: normal gun (medium range balanced), sniper rifle (scoped long range), shotgun (close range spread), machine gun (high fire rate with spread) \u2014 each needs distinct effective ranges and spread patterns to feel differentiated"},{"t":"shooting","f":"Machine gun spread pattern must be tuned carefully \u2014 too wide a spread cone makes bullets miss at any practical range, effectively hitting behind the player's intended target"},{"t":"fps","f":"FPS UI should provide all necessary player information (health, ammo, minimap) \u2014 removing UI entirely in favor of 'immersion' removes critical gameplay feedback"},{"t":"physics","f":"Rapier physics engine integrated via @react-three/rapier; wrap Experience component in <Physics> component to enable physics simulation"},{"t":"physics","f":"Stage platform built as low-height cylinder using RigidBody with type='fixed' and explicit cylinder collider (colliders='force') so it blocks objects but doesn't move"},{"t":"interior","f":"MeshReflectorMaterial from drei used to create reflective floor; fog added to blend background objects with the floor for depth effect"},{"t":"interior","f":"GLTF models loaded via useGLTF hook; gltfjsx CLI tool auto-generates React Three Fiber component code from .gltf model files"},{"t":"interior","f":"Text3D component from drei renders 3D text; requires facetype.json font generated from facetype.js; subset characters to reduce file size (20MB full Japanese font reduced to 87KB by including only needed characters)"},{"t":"interior","f":"Zustand used for game state management over React Context (causes re-renders) and Redux (too verbose); game level generator creates array of stages with increasing difficulty by adding more options per stage"},{"t":"interior","f":"Scene lighting uses ambientLight intensity=1 plus directionalLight for shadows; background color set on Canvas component"},{"t":"terrain","f":"Stamp-based terrain sculpting uses a free Unity package called 'Stamp It' where you set stamp height, adjust brush size, and set 'stamp from current height' value to 1 to stack terrain stamps additively"},{"t":"terrain","f":"Procedural Terrain Painter auto-textures terrain using layered rules: higher layers in the stack cover layers below, each layer supports modifiers like 'height' (with max height and max falloff) and 'slope' (to place rock textures on slopes), and multiple modifiers can be combined per layer"},{"t":"water","f":"Unity's built-in Water Surface River object is added via right-click, positioned at terrain center, raised to desired height, rotated and scaled to cover the area, with 'distance wind orientation' controlling river flow direction"},{"t":"terrain","f":"Mass tree placement uses Unity's 'MPL three' option to batch-place vegetation (e.g., 5000 or 10000 models at once) across the entire terrain surface, with tree height min/max controlling model size variation"},{"t":"terrain","f":"Unity Terrain Tools package (installed via Window > Package Manager > Unity Registry) adds 'Spine Details' for grass placement that auto-mixes multiple grass models using 'Target Density' to control frequency of each model type"},{"t":"terrain","f":"Terrain Tools brush mask filters (added via + button) include a 'Layer' filter that restricts detail painting to a specific texture layer with adjustable sharpness, enabling large-area detail placement constrained to specific terrain material zones"},{"t":"terrain","f":"Realistic forests require vegetation of different heights to simulate natural forest layers (canopy, understory, ground cover), combining trees, smaller vegetation, and grass models"},{"t":"interior","f":"In-game phone UI built as UMG Widget Blueprint (WB_Phone) using canvas panels: CP_Phone for outer container, CP_Screen for the screen area, with phone image set to 407x792 pixels matching the 3D phone model dimensions"},{"t":"interior","f":"Phone screen region defined by manually dragging canvas panel anchor points to match the screen portion of the phone image, then child elements use full-size anchors within that constrained CP_Screen canvas"},{"t":"interior","f":"Phone widget centering done via Ctrl+Alt+Shift click on center anchor preset to set pivot to middle, then canvas set to 'desired' size mode instead of 'fill screen' to match phone dimensions"},{"t":"interior","f":"Phone background wallpaper uses image tiling setting on the UMG Image widget to prevent squashing, combined with a background tint color (blue) for visual polish"},{"t":"interior","f":"Doors in hub areas are modeled as visual props that don't lead anywhere \u2014 hallways surrounding the player terminate into void, creating the illusion of a larger space while keeping the playable area minimal."},{"t":"interior","f":"A one-sided piece of geometry is placed directly behind the player's cart to create the illusion that track fades out of existence, hiding the fact that the track model extends far behind the player."},{"t":"interior","f":"Doorway transitions use pitch-black post-processing and a white sphere at the end of the passage; when the player reaches the sphere, the cart immediately stops and the scene cuts to the hub area."},{"t":"interior","f":"Billboards along the intro track are all pre-loaded and visible in the scene but only illuminate as the player passes by them, using lighting activation rather than spawn/load triggers."},{"t":"interior","f":"The prize crane mechanism teleports back to its original suspended position behind a back wall after leaving the player's sight, rather than animating a return path."},{"t":"interior","f":"Room exteriors are covered in a default/placeholder texture since the player is never meant to see them; only interior-facing surfaces receive final art."},{"t":"interior","f":"Hidden objects placed out of bounds include a disc-shaped flashing light and an 'end Showtime' button positioned to the right of the stage area, used as developer control assets."},{"t":"interior","f":"A 360\u00b0 immersive room requires multiple projectors, computers, and projection mapping software to create seamless interior environments"},{"t":"interior","f":"Remote debugging of a multi-projector immersive room setup can be completed within 30 minutes when using projection mapping software"},{"t":"interior","f":"Adding sensors to an immersive projection room enables interaction with virtual content, allowing users to trigger and manipulate scene elements"},{"t":"vehicles","f":"Car movement and logic built iteratively in three.js with checkpoints and booster sections as core game mechanics"},{"t":"city","f":"Environment blocked out first in Blender focusing on track layout and feel before adding detail"},{"t":"rendering","f":"Lights set up in Blender and baked into lightmaps for optimal web performance rather than using real-time lighting"},{"t":"rendering","f":"Low-poly assets modeled and textured in Blender to add detail while keeping geometry count browser-friendly"},{"t":"vehicles","f":"Checkpoints and booster sections implemented as track mechanics to structure race progression and add speed variation"},{"t":"npc","f":"City Sample Crowds in UE 5.5 requires enabling the MassAI (MCrow) plugin, then adding the City Sample Crowds content package (select 5.3 version as no 5.5-specific update exists)"},{"t":"npc","f":"BP_CrowdCharacter blueprint must be reparented from SkeletalMeshActor to Character class, then all 5 SkeletonMeshComponent references must be replaced with the new mesh component"},{"t":"npc","f":"MassAgent component requires 3 entity config traits: AgentCapsuleCollisionSync (set to ActorToMass with ZSync transform deselected), AgentMovement (MassToActor), and AgentOrientationZ (MassToActor)"},{"t":"npc","f":"UE 5.5 introduces a new error in the GetSafeCopy function of BP_CrowdCharacter; fix by clicking MakeArray, deleting the empty array element, and recompiling"},{"t":"city","f":"ZoneGraph system uses ZoneShapes placed in levels with Lane Profiles containing forward and backward lanes (set width to 100); must enable Show > Developer > ZoneGraph in viewport to visualize shapes"},{"t":"npc","f":"ZoneShape Lane Profiles require custom tags (e.g., 'Peds') to be created and assigned, with the default tag deselected, to properly route crowd agents"},{"t":"npc","f":"Skeletal mesh components must be moved one-by-one into the Mesh component hierarchy and positioned inside the capsule collider; moving all at once can crash the editor"},{"t":"city","f":"Unity terrain detail distance must be increased (e.g., 250) to render grass/details visible from the player's position; default is too low for open worlds"},{"t":"city","f":"Fog density of approximately 0.0045 with color sampled from the low horizon of the skybox creates a cohesive fade that hides terrain detail pop-in boundaries"},{"t":"city","f":"Unity Mass Place Trees feature can batch-place 15,000 trees across an entire terrain in one operation, but tree distance in terrain settings must be increased to render distant trees"},{"t":"city","f":"Terrain brush size of ~400 gives coarse landscape height passes, then reducing to ~200 adds finer terrain detail; use a brush with noise for natural-looking elevation"},{"t":"city","f":"For grass detail textures, sample the healthy color from lighter parts of the base ground texture and the dry color from darker parts using the eyedropper to maintain color cohesion"},{"t":"city","f":"A cohesive open world scene requires color-sampling consistency: skybox horizon color for fog, base texture colors for grass healthy/dry tints, and tree prefab materials matching the grass environment"},{"t":"npc","f":"Replica AI NPC demo requires a 28 GB download, runs via a local setup/install process, and processes voice input with variable response latency \u2014 sometimes noticeably longer than real-time conversational pace"},{"t":"npc","f":"AI NPCs maintain per-character personality and emotional state: different NPCs respond with distinct attitudes (hostile, dismissive, helpful) and can escalate or de-escalate based on player tone and conversation history within a session"},{"t":"npc","f":"AI NPCs can process contextual environmental queries (e.g., weather, directions to landmarks like a park) and generate spatially-aware responses such as 'go straight down the street and take a left at the next corner'"},{"t":"city","f":"The demo city environment includes sidewalks, streets with vehicle traffic (including box trucks), stairs, and pedestrian NPCs walking routes \u2014 but has visible boundary limits referred to as 'the Matrix wall'"},{"t":"vehicles","f":"The demo features AI-driven traffic with vehicles like box trucks navigating city streets, and NPCs contextually reference the traffic conditions (e.g., 'the traffic's ridiculous') when prompted"},{"t":"npc","f":"Voice-to-voice NPC interaction uses a pipeline of speech recognition \u2192 AI text generation \u2192 text-to-speech, with the latency gap visible between player speech ending and NPC audio response beginning"},{"t":"npc","f":"The Unrecord game (police game) shares assets with the Replica demo (e.g., the same box truck model appears in both), indicating asset reuse across AI NPC tech demos and game prototypes"},{"t":"shooting","f":"Bullet movement uses rotation basis multiplied by speed constant (set to 40) in the process function to move projectiles forward along their local negative Z axis"},{"t":"shooting","f":"Shoot animation length is 0.1 seconds (a tenth of a second) with snapping set to 100, using 3 keyframes: original position, gun pulled back, return to original position \u2014 only the middle keyframe position changes"},{"t":"shooting","f":"Fire rate control checks if shoot animation is NOT currently playing before allowing another shot \u2014 if animation finished or button just pressed, play shoot animation again"},{"t":"shooting","f":"Bullet mesh is a BoxMesh with X and Y dimensions set to 0.05, with emission color at strength 5 for a glowing projectile effect"},{"t":"shooting","f":"Gun barrel spawn point uses a RayCast3D with target_position set to negative Z (0, 0, -1) since negative Z is the forward direction in Godot's coordinate system"},{"t":"shooting","f":"Bullet collision detection uses a RayCast3D attached to the bullet with length slightly exceeding the mesh bounds, pointing in negative Z direction"},{"t":"fps","f":"Gun is parented as child of the camera node, positioned using camera preview checkbox to see first-person view without running the game; shadow casting is disabled on gun mesh via cast_shadow setting in geometry section"},{"t":"shooting","f":"Hitscan bullets have zero travel time and hit whatever is at the crosshair center instantly when the trigger is pulled. Projectile bullets send a physical in-game object with real travel time requiring the player to lead shots on moving targets."},{"t":"shooting","f":"Bullets can originate from the center of the camera (between the eyes) or from the gun barrel. Camera-origin means the bullet naturally hits where the crosshair points. Games like Overwatch, Apex Legends, and CS:GO shoot from the camera/eyes."},{"t":"shooting","f":"Camera-origin shooting enables 'head glitching' where players shoot from behind cover as long as their head is unobstructed. The fix is to move the camera down to about chest height so the view is obstructed when behind cover."},{"t":"shooting","f":"For camera-origin projectiles, a fake cosmetic bullet is fired from the gun barrel for visual effect while the real invisible projectile originates from the camera center. In Overwatch, projectiles near wall edges pass through visually but the real hitbox projectile never collides with the wall."},{"t":"shooting","f":"Barrel-origin shooting (used by PUBG, Escape from Tarkov, TF2 Soldier's rocket launcher) causes bullets to hit slightly off-center from the crosshair unless the developer compensates. Players must offset aim when hip-firing and watch for walls blocking the barrel's line of fire."},{"t":"shooting","f":"With barrel-origin bullets, enemies who get between the player and the gun barrel tip cannot be hit even if the crosshair is on them, because guns have physical length. Games handle this by pulling the gun model back near objects or disabling shooting at very close range."},{"t":"shooting","f":"A hybrid bullet type exists where bullets are hitscan up to a certain distance and become projectiles beyond that threshold. Used in some Halo games and Insurgency: Sandstorm to give close-range weapons like SMGs immediacy while limiting long-range sniper effectiveness."},{"t":"recoil","f":"Prodeus uses per-shot screen shake (screen vibration on every gunshot) as a recoil-feel mechanic, giving visceral feedback without complex recoil patterns"},{"t":"ammo","f":"Ultrakill replaces traditional ammo/health pickups with a blood-as-fuel mechanic where killing enemies at close range refills health, encouraging aggressive play"},{"t":"ammo","f":"Prodeus horror mods use severely limited ammo pools combined with restricted lighting to shift the genre from action shooter to survival horror within the same engine"},{"t":"hitscan","f":"Ultrakill features a fist-parry mechanic that reflects enemy bullets back, implying projectile-based (non-hitscan) bullets that can be intercepted and redirected mid-flight"},{"t":"impact_force","f":"Prodeus enemies use high-pressure blood-explosion death effects (described as 'blood pinatas') with gore that coats the player's gun model and environment walls"},{"t":"shooting","f":"Ultrakill implements a coin-toss trick-shot system where firing a bullet at a thrown coin redirects it toward enemies, combining projectile physics with precision timing"},{"t":"weapon_setup","f":"To attach a weapon model in Unity FPS, drag the model inside the player hierarchy alongside the dummy weapon, then align its transform position to match the dummy weapon's position."},{"t":"weapon_setup","f":"After importing a weapon prefab, right-click and select 'Prefab > Unpack Completely' to break the prefab link so individual parts can be freely modified."},{"t":"weapon_setup","f":"Weapon model scale often needs manual adjustment after import; e.g. a pistol prefab was scaled to 2x its default size to look correct in first-person view."},{"t":"rendering","f":"Pink/magenta materials on imported weapon models indicate a shader mismatch; fix by selecting all materials then using Edit > Rendering > Materials > Convert Selected Built-in Materials to URP."},{"t":"shooting","f":"Camera raycast aiming works by casting a ray from screen center, then faking the bullet trail from the gun barrel to the hit point; trails play fast enough that imperfect angles are unnoticeable"},{"t":"shooting","f":"Camera raycast method causes bullet trails to clip through walls near the gun because the ray originates from the camera while the trail renders from the gun barrel, creating a perspective mismatch"},{"t":"shooting","f":"Third-person shooters exacerbate the camera-vs-gun offset problem because the camera is significantly farther from the gun than in first person, and objects can pass between camera and player causing backward shots"},{"t":"shooting","f":"Barrel-origin shooting (raycast or projectile from gun muzzle) is the most realistic but makes crosshair placement difficult because gun model sway causes the aim point to shift constantly"},{"t":"shooting","f":"A hybrid aiming method uses a camera raycast to find a world-space target point, then aims the gun barrel toward that point and fires the projectile from the gun, combining camera-based targeting with barrel-origin bullets"},{"t":"shooting","f":"Three standard aiming implementations: (1) camera raycast with faked bullet trail from gun, (2) direct barrel-origin raycast/projectile, (3) hybrid where gun aims at camera raycast hit point then fires from barrel"},{"t":"tps","f":"Camera follow uses a CameraHolder empty object with child camera; a CamPos transform (Y=2.6) inside the player is tracked each Update via transform.position = camPos.position for direct position lock"},{"t":"tps","f":"Mouse look uses Input.GetAxisRaw MouseX/MouseY multiplied by sensitivity (100) and 0.01f; vertical rotation (X axis) is clamped to -90..90 degrees via Mathf.Clamp"},{"t":"tps","f":"Orientation is a separate empty child object inside the player whose rotation is set to Quaternion.Euler(0, yRotation, 0); camera transform gets Quaternion.Euler(xRotation, yRotation, 0) \u2014 decoupling body yaw from camera pitch"},{"t":"tps","f":"Player movement direction is calculated as orientation.forward * yInput + orientation.right * xInput, then force is applied to Rigidbody in FixedUpdate with moveSpeed=10"},{"t":"tps","f":"Rigidbody is configured with Interpolate=Interpolate and CollisionDetection=ContinuousDynamic; rb.freezeRotation=true is set in Start to prevent physics-driven rotation"},{"t":"tps","f":"Cursor is locked and hidden at Start via Cursor.lockState=CursorLockMode.Locked and Cursor.visible=false"},{"t":"tps","f":"Right stick rotates camera up/down and around the character providing full orbit control in third person view"},{"t":"tps","f":"Left stick analog sensitivity controls locomotion blend: soft press triggers walk animation, full tilt triggers sprint animation"},{"t":"tps","f":"Ground detection uses raycasting to know when the character has hit the ground for ground checks and landing animations"},{"t":"tps","f":"Unity new Input System package required for simultaneous mouse/keyboard and controller support in third person controller"},{"t":"tps","f":"Standard/built-in pipeline materials convert to URP via Window > Rendering > Render Pipeline Converter using upgrade materials then initialize and install"},{"t":"tps","f":"Character materials use Universal Render Pipeline Lit shader with albedo base map, normal map, and metallic smoothness map slots"},{"t":"tps","f":"Unity Starter Assets Third Person Controller uses a CineMachine camera (player follow camera) for third person camera control, separate from the main camera"},{"t":"tps","f":"The Starter Assets third person controller prefab must be unpacked completely (right-click > unpack prefab completely) before customization, and the scene's existing main camera must be removed first"},{"t":"tps","f":"Unity third person controller supports WASD movement, sprint, jump with sound effects, and CineMachine-driven camera orbit control out of the box with zero additional scripting"},{"t":"tps","f":"To retarget a Mixamo or third-party character mesh to Unity's third person controller, set the imported FBX model rig type to Humanoid and hit Apply, which maps the skeleton to Unity's humanoid avatar system"},{"t":"tps","f":"When swapping character meshes, the new mesh is placed inside the PlayerArmature > Root > Geometry hierarchy, and the transform must be reset (right-click transform > Reset) to align it to the correct position"},{"t":"tps","f":"Mixamo FBX exports for Unity should use FBX for Unity format with the character kept in T-pose (original position) to ensure correct animation retargeting"},{"t":"tps","f":"In Unreal Engine, skeletal mesh components have 'Only Owner See' and 'Owner No See' boolean properties under Rendering > Advanced that control per-player mesh visibility in multiplayer."},{"t":"tps","f":"For the first-person mesh: set 'Only Owner See' = true and 'Owner No See' = false. For the third-person mesh: set 'Only Owner See' = false and 'Owner No See' = true."},{"t":"tps","f":"With Owner No See enabled on the third-person mesh, the owning player cannot see their own third-person shadow or legs when looking down, confirming the mesh is fully hidden locally."},{"t":"tps","f":"In a Listen Server setup with two players, each player's pawn has both a first-person skeletal mesh (FPS arms/weapon) and a separate third-person skeletal mesh (full body) attached simultaneously."},{"t":"tps","f":"Using F8 (Eject/Possess) in editor reveals both the first-person and third-person meshes simultaneously since camera ownership rules no longer apply to the detached spectator view."},{"t":"tps","f":"Cinemachine FreeLook camera uses follow and lookAt targets set to the player character to create an orbiting third person camera"},{"t":"tps","f":"FreeLook camera X-axis speed controls horizontal orbit rate (default was high, reduced to 100 for smoother rotation) and Y-axis speed controls vertical look (reduced to 4 for smoother vertical panning)"},{"t":"tps","f":"Cinemachine FreeLook camera is preferred over vcam for third person because it provides full orbital mouse-driven rotation around the character on both X and Y axes"},{"t":"tps","f":"Camera smoothing in third person is achieved by tuning X-axis and Y-axis speed values lower \u2014 reducing X-axis from default to ~100 and Y-axis to ~4 eliminates jerky rotation"},{"t":"tps","f":"Third person character velocity can be adjusted independently from camera speed to control movement feel without affecting camera orbit behavior"},{"t":"tps","f":"Use ForceMode.VelocityChange when adding force to a rigid body player controller \u2014 this ensures velocity changes are not affected by the rigid body's mass or the physics simulation step length"},{"t":"tps","f":"Apply high drag only while the player is grounded and low drag while airborne \u2014 constant high drag causes floating/gliding when walking off edges"},{"t":"tps","f":"Never directly set rigid body velocity every physics frame \u2014 it breaks the physics simulation; use AddForce instead as recommended by Unity documentation"},{"t":"tps","f":"Ground checking with a single raycast is inaccurate \u2014 use a sphere cast or OnCollisionEnter, then verify the hit is actual ground by checking the slope angle (angle between player down vector and surface normal) against a threshold"},{"t":"tps","f":"Wall collisions can falsely register as ground \u2014 fix by assigning ground objects to a dedicated physics layer or by comparing the slope angle between the player's down vector and the contact normal"},{"t":"tps","f":"For character controller + physics interaction, apply a force at each contact point in the direction of the surface normal on every rigid body the controller touches"},{"t":"cannon.js_vehicle_physics","f":"Cannon.js physics engine combined with React Three Fiber enables car physics with angular velocity control while airborne, allowing flip tricks off ramps"},{"t":"react_three_fiber_scene_setup","f":"All Three.js scripts must be wrapped under the Canvas component because React Three Fiber hooks cannot be used outside of Canvas"},{"t":"3d_environment_map","f":"A 3D scene background can be created using an environment map loaded via the Environment component, producing a blurred background that supports orbit controls"},{"t":"third_person_camera","f":"A toggleable third-person camera view can be implemented alongside orbit controls for vehicle-based gameplay in React Three Fiber"},{"t":"physics_colliders","f":"Scene elements like trees, signs, and ramps can act as physics colliders in cannon.js, enabling realistic collision responses for vehicles"},{"t":"react_three_fiber_dependencies","f":"Core dependency stack for a 3D physics game: three.js, @react-three/fiber, @react-three/drei (utility functions), and @react-three/cannon (physics) \u2014 pin exact versions for stability"},{"t":"hitscan","f":"Hitscan weapons perform instant ray checks from crosshair to target \u2014 if the crosshair is on the enemy at fire time, it registers a hit with zero travel time, making accuracy a pure aim check."},{"t":"hitscan_ai","f":"AI bots with hitscan weapons can theoretically hit 100% of shots since there is no projectile to dodge \u2014 accuracy must be artificially limited by programming inaccuracy or the bot effectively becomes unavoidable damage-over-time."},{"t":"hitscan_counterplay","f":"Movement speed can serve as implicit hitscan counterplay \u2014 bots are typically programmed to be less accurate against faster-moving targets, letting games like Titanfall 2 use high-speed movement to simulate the dodge dynamics of projectile weapons."},{"t":"bullet_spread","f":"Counter-Strike adds depth to hitscan by requiring players to learn per-weapon spray patterns, control fire rate to allow aim reset, and stand still while shooting \u2014 turning accuracy into a technical skill layer on top of basic aim."},{"t":"projectile_counterplay","f":"Projectile weapons have inherent counterplay because shots are visible and have travel time \u2014 players can dodge by moving radically or increasing distance, which increases the lead prediction required by the shooter."},{"t":"hitscan_design","f":"FEAR makes hitscan work by having enemy soldiers vocally narrate their actions (flanking, grenading, etc.), turning cover-based hitscan counterplay from passive waiting into active tactical decision-making."},{"t":"shooting","f":"Hitscan shooting uses Physics.Raycast originating from the camera position in the forward direction; if nothing is hit, no action is taken"},{"t":"shooting","f":"A gun script requires configurable public floats: damage (default 10) and range (default 100 units)"},{"t":"shooting","f":"Input.GetButtonDown('Fire1') maps to the left mouse button by default in Unity and is used to trigger the shoot function"},{"t":"shooting","f":"RaycastHit stores information about what the ray collided with, enabling damage application and impact effects"},{"t":"shooting","f":"Gun graphics should be parented to the main camera, and the camera's near clipping plane must be decreased to prevent the gun model from being clipped"},{"t":"shooting","f":"Raycast hitscan guns can apply an impact force to physics objects on hit, in addition to damage and visual effects like muzzle flash and impact particles"},{"t":"shooting","f":"Hitscan guns use Physics.Raycast instead of spawning a rigidbody bullet game object, determining hits instantly in one frame"},{"t":"shooting","f":"Hitscan bullet trails use a TrailRenderer that goes from the shot origin point to the raycast hit point, with an impact particle system spawned at the hit location"},{"t":"shooting","f":"Hitscan shooting requires only 2 scripts: a Gun script (attached to the weapon game object) and a PlayerAction script (attached to the player capsule) that calls gun.shoot()"},{"t":"shooting","f":"Unity's new Input System uses Send Messages behavior to call an OnShoot method on all scripts attached to the game object with PlayerInput, triggered by a custom 'shoot' action bound to left mouse button"},{"t":"shooting","f":"The Gun reference in PlayerAction is a private serialized field ([SerializeField] private Gun gun) so it can be assigned in the Unity Inspector rather than hardcoded"},{"t":"camera","f":"Camera follow is implemented by creating a 'camera holder' empty object, making the camera a child of it, then in Update setting transform.position = camPos.position where camPos is a transform reference point parented to the player at Y offset 2.6"},{"t":"FPS","f":"First-person mouse look uses two floats x and y, accumulating input via y += Input.GetAxisRaw('Mouse X') * sensX * 0.01f and x -= Input.GetAxisRaw('Mouse Y') * sensY * 0.01f, then clamping x with Mathf.Clamp(x, -90, 90)"},{"t":"FPS","f":"Camera rotation is split: orientation.rotation = Quaternion.Euler(0, y, 0) for horizontal yaw on a separate orientation object, and transform.rotation = Quaternion.Euler(x, y, 0) for the camera itself combining pitch and yaw"},{"t":"FPS","f":"Movement direction is calculated as Vector3 moveDirection = orientation.forward * yInput + orientation.right * xInput, then force is applied to the Rigidbody so movement aligns with camera yaw without pitch influence"},{"t":"FPS","f":"Rigidbody is configured with Interpolate set to 'Interpolate' and Collision Detection set to 'Continuous Dynamic', with rb.freezeRotation = true in Start to prevent physics-driven rotations"},{"t":"camera","f":"Camera follow target (camPos) is placed as a child of the player object at local position Y = 2.6, representing approximate eye height above the player capsule origin"},{"t":"FPS","f":"Mouse sensitivity values are set to approximately 100 for both X and Y axes, multiplied by 0.01f in code (effective multiplier 1.0), with cursor locked via Cursor.lockState = CursorLockMode.Locked and Cursor.visible = false"},{"t":"camera","f":"Spring arm (camera boom) target arm length set to 200-250 units for third-person follow camera; socket offset Y = 35; target offset Z = 60"},{"t":"camera","f":"Custom event 'MoveCamera' takes two float inputs: TargetArmLength and SocketYOffset, with variables LastSocketY and LastArmLength storing current values before interpolation"},{"t":"camera","f":"Camera boom current values cached by reading GetSocketOffset.Y into LastSocketY and GetTargetArmLength into LastArmLength before any transition begins"},{"t":"camera","f":"Timeline node 'CameraFloat' with length 1 second drives the interpolation; keyframes at (0, 0) and (0.7, 1) with first keyframe set to Auto tangent for smooth easing"},{"t":"camera","f":"Lerp node interpolates TargetArmLength: A = LastArmLength, B = target input value, Alpha = timeline float output; result fed into SetTargetArmLength on camera boom each tick (Update pin)"},{"t":"camera","f":"Second lerp node interpolates SocketOffset.Y: A = LastSocketY, B = target SocketYOffset input, Alpha = same timeline float; result fed into SetSocketOffset split Y pin"},{"t":"camera","f":"Sprint triggers MoveCamera with extended arm length (e.g. 250) to pull camera further back; returning to walk resets to default values via StopCamera and ResetCamera custom events on timeline Stop/NewTime pins"},{"t":"collision","f":"Door interaction box collision dimensions: X scale 2.5, Y scale 1.75, Z scale 3.45 \u2014 sized to encompass both the player character and the door swing radius."},{"t":"collision","f":"Door system uses a scene component called 'door open location' as a child of the door mesh to define the target transform for open/partial-open states, separate from the collision volume."},{"t":"camera","f":"Resident Evil door transitions use a three-state enumeration cycle: Closed \u2192 Partially Open \u2192 Open, repeating in order, to control door animation and camera behavior during traversal."},{"t":"camera","f":"Spring arm (camera boom) socket offset of X:0, Y:60, Z:60 with target arm length 120 creates a dead-space style over-the-shoulder third-person camera"},{"t":"camera","f":"Store the starting socket offset in a variable at BeginPlay so aim-to-unaim transitions can restore the original camera position instead of resetting to 0,0,0"},{"t":"camera","f":"Set ViewPitchMax to 40 degrees via GetPlayerCameraManager to prevent extreme vertical camera rotation in third-person mode"},{"t":"camera","f":"Camera boom socket offset X controls forward/back, Y controls left/right shoulder offset, Z controls height offset relative to the follow target"},{"t":"camera","f":"Over-the-shoulder aim mode transitions involve interpolating the socket offset from a wider TPS position to a tighter aim position, triggered by right mouse button input"},{"t":"camera","f":"Camera setup logic should be encapsulated in a dedicated function (e.g. SetUpCamera) called once from BeginPlay to cache initial spring arm values before any runtime transitions modify them"},{"t":"camera","f":"For true first person in UE5, delete the spring arm component and parent the camera directly to the skeletal mesh component, then set the parent socket to 'head'"},{"t":"camera","f":"Camera transform for true first person on helmeted character: location offset (10, 20, 290) and rotation 90 degrees to align forward with character facing direction"},{"t":"camera","f":"Camera must be rotated 90 degrees on one axis after parenting to head socket to correct the default orientation so the view faces forward"},{"t":"camera","f":"For characters with large head geometry (helmets), push the camera location further forward from the head socket to prevent the mesh clipping into view"},{"t":"camera","f":"Head-parented camera inherits all skeletal animation motion, causing significant wobble during combat animations designed for third person"},{"t":"FPS TPS","f":"Converting TPS to true FPS requires duplicating the entire player character blueprint hierarchy (base player, full player, final player) and reparenting each layer to maintain framework functionality"},{"t":"FPS TPS","f":"True first person (camera on head bone) lets the player see their full body when looking down, unlike viewport-only first person which hides the body"},{"t":"collision","f":"Use sphere cast instead of single raycast for ground checking \u2014 a raycast will falsely report the player is airborne when standing on an edge, while a sphere cast covers more area beneath the collider"},{"t":"collision","f":"Make the sphere cast radius slightly smaller than the character collider radius so it won't register wall contacts as ground contacts, though this can introduce other edge cases"},{"t":"collision","f":"Validate ground contacts by checking slope angle: compute the angle between the player's down vector and the surface normal vector, and only register as ground if the angle is below a threshold"},{"t":"collision","f":"For character controller physics interaction with rigidbodies, apply a force at each contact point in the direction of the surface normal for every contact the character controller makes"},{"t":"collision","f":"Use ForceMode.VelocityChange when adding movement force to a rigidbody player controller \u2014 this makes velocity changes independent of rigidbody mass and physics timestep length"},{"t":"collision","f":"Apply high drag on a rigidbody controller only while grounded and set drag much lower when airborne \u2014 grounded-only high drag fixes slipperiness, while low air drag prevents floating/gliding when walking off edges"},{"t":"collision","f":"On slopes, project the movement force vector to be parallel to the ground surface using the ground normal, and add an upward counter-force to counteract gravity \u2014 otherwise the player moves slower uphill, faster downhill, and slides when stationary"},{"t":"buoyancy","f":"Buoyancy force is calculated as Vector3.up multiplied by floatingPower multiplied by the difference between water height and rigidbody Y position, so deeper submersion produces stronger upward force"},{"t":"buoyancy","f":"ForceMode.Force is used when applying the upward buoyancy force to the rigidbody, which accounts for mass and applies force over time rather than as an impulse"},{"t":"buoyancy","f":"Underwater drag values of 3 (linear) and 1 (angular) versus air drag values of 0 (linear) and 0.05 (angular) are used, switching between them based on whether the object is submerged"},{"t":"buoyancy","f":"A waterHeight float defines the Y-level of the water plane, and the difference between waterHeight and the rigidbody's Y position determines submersion depth and force magnitude"},{"t":"buoyancy","f":"The script uses RequireComponent(Rigidbody) attribute and runs buoyancy logic in FixedUpdate since it is physics-based, with a boolean tracking whether the object is currently underwater"},{"t":"buoyancy","f":"The water surface is a plane with its collider removed, serving only as a visual reference while the waterHeight float handles the actual physics boundary"},{"t":"water","f":"Water material controls normal map, scattering, color tints, reflections, foam settings, and SSS (subsurface scattering) tint to adjust overall water appearance"},{"t":"water","f":"Foam generation is driven by shallow depth \u2014 shallower areas produce more foam, with adjustable foam strength that updates in real-time during rendering"},{"t":"water","f":"Wave animation uses an FFT (Fast Fourier Transform) shape component on a separate game object to generate animated waves"},{"t":"water","f":"Water system requires linear color space (not gamma) set in Project Settings > Player > Other Settings for correct rendering"},{"t":"water","f":"Ocean rendering uses a LOD system with underwater support, surface clipping, acoustic simulation, and scattering \u2014 all as modular add-on components"},{"t":"water","f":"Water system supports physics interaction allowing objects to be affected by water buoyancy and wave forces"},{"t":"water","f":"Gerstner waves combine multiple sine waves to create complex ocean surfaces; more waves increase computational cost proportionally."},{"t":"water","f":"Ocean mesh is a plane with LOD that gradually reduces detail from center outward; since waves are world-space, the mesh moves with the player to simulate an infinite ocean."},{"t":"water","f":"Distant waves use scrolling normal map textures on a completely flat surface instead of Gerstner displacement, saving GPU cost since the player never gets close."},{"t":"water","f":"Ocean height data is rendered to a Render Target so any object in the world can cheaply sample wave height instead of recalculating Gerstner equations per-object; limitation is no rotation data is available."},{"t":"water","f":"Surface foam is added during stormy weather by increasing wave height and sharpness, combined with Niagara particle splashes spawned on wave peaks via a scratch pad module that samples the wave render target and destroys particles on low waves."},{"t":"water","f":"Fake god rays are created in a fog material by stretching a noise texture in the light direction to brighten the fog, faded out over depth; volumetric shadow methods and shadow-casting planes were rejected due to visual artifacts."},{"t":"water_volume_setup","f":"ACF (Advanced Character Framework) uses a Physics Volume actor to define swimmable water areas. Place the volume to cover the water region and enable the 'Water Volume' flag so the framework auto-detects swim state."},{"t":"swim_trigger","f":"Swimming is triggered by character overlap with the Physics Volume; exiting the volume immediately reverts the character to ground locomotion (walk/run blend space)."},{"t":"water_surface_alignment","f":"The top face of the Physics Volume should be aligned with the water surface mesh so the swim-to-walk transition matches the visible waterline and avoids awkward blending near the shore."},{"t":"swim_blend_space","f":"ACF uses a blend space for swim animations that activates automatically when the Water Volume flag is enabled on the physics volume \u2014 no additional animation blueprint wiring is required."},{"t":"water_color_absorption","f":"Water color is implemented via light absorption formula: absorption_coefficient = percentage of light absorbed, using formula where alpha is absorption coefficient, a is percentage absorbed, x is material thickness. The absorption value is subtracted from scene color rather than multiplied."},{"t":"water_transparency","f":"Water transparency uses the Scene Color node (screen color buffer before water plane renders) instead of alpha output. The shader must be marked as transparent to access pre-rendered screen content."},{"t":"water_depth_fade","f":"Water color changes based on depth: deeper water absorbs more color. Depth is calculated from camera position using the Scene Depth node (camera depth buffer before object renders), determining how much water the viewer is looking through."},{"t":"water_absorption_color_inversion","f":"To select a desired water color instead of an absorption color, use one_minus(waterColor) to derive the absorption color. This inverts the target color so the absorption process yields the intended final water color."},{"t":"water_shader_components","f":"A complete water shader consists of: transparency, color absorption, caustics, reflectiveness, aeration (foam/bubbles), and aeration movement. Each can be implemented as separate modules."},{"t":"water_absorption_formula","f":"Absorption formula nodes: absorption_coefficient controls how far light travels through material before fully absorbed, varies per wavelength and material. Result is multiplied by absorption color to get percentage of color visible, then subtracted from scene color."},{"t":"HDRP water setup","f":"Unity HDRP water system requires version 16+ of HDRP package and Unity 2023.2+; water surfaces are added via hierarchy right-click > Water menu with options for ocean/sea/lake, pool, and river"},{"t":"HDRP water rendering pipeline","f":"Full water rendering requires enabling multiple pipeline features: water simulation, deformation, water foam, script interactions, surface decals, screen space reflections, and transparent screen reflections"},{"t":"HDRP water surface types","f":"The HDRP water system provides distinct surface types: Ocean/Sea/Lake for large bodies, Pool for contained water, and River for flowing water, plus auxiliary tools including excluder, deformer, and foam generator"},{"t":"HDRP water visual features","f":"The water system supports waves, ripples, foam, underwater caustics, refractions, reflections, and deformation simulation as built-in features"},{"t":"HDRP water samples","f":"Unity provides importable water sample scenes via Package Manager > HDRP > Samples > Water Samples, including an Island scene pre-configured with correct water rendering settings"},{"t":"HDRP water deformation","f":"Water deformation is a separate render pipeline feature that must be enabled independently from base water rendering in the HDRP quality asset settings"},{"t":"water","f":"Stylized Water for URP requires Unity 2019.3.9+ and supports buoyancy, waves, foam, refraction, planar reflections, and custom lighting"},{"t":"water","f":"Water depth rendering uses shallow color near objects and deep color at edges, with configurable horizon settings and shore edge blending"},{"t":"water","f":"Surface foam uses texture-based alpha cutoff, distortion amount, configurable scale, direction, and speed for both primary and secondary foam layers"},{"t":"water","f":"Intersection effects detect world objects intersecting water and apply configurable direction, scale, and blending at contact points"},{"t":"water","f":"Asset includes specialized prefabs for beach cascading water, buoyancy floating objects, object interaction with planar reflections, and stylized game water"},{"t":"water","f":"Foam shadows can be enabled separately with configurable strength, intersection amount, and foam effect intensity"},{"t":"proc-gen","f":"Unconstrained random generation produces white-noise output \u2014 blocks everywhere with no terrain contour; constraints must enforce dirt-on-surface, no sky blocks, consistent terrain flow, and tree self-similarity to produce playable worlds."},{"t":"proc-gen","f":"Even with constraints, undesirable edge cases slip through \u2014 ranging from funny quirks to full unplayability (e.g., Terraria spawning a player surrounded by impassable stone). At 1% failure rate with millions of players, thousands get broken worlds."},{"t":"proc-gen","f":"Procedural generation is not inherently random \u2014 results can be deterministic (same seed = same output). Randomness is opted into specifically to produce unpredictable variety; without that goal, manual authoring is preferred."},{"t":"proc-gen","f":"The core engineering tradeoff: enough variance to keep gameplay unique and replayable vs. enough constraints to prevent unplayable degenerate cases. Tightening constraints reduces variety; loosening them increases failure rate."},{"t":"proc-gen","f":"High-fidelity games (e.g., God of War) still use procedural generation during development for element placement like foliage positions, but artists make the final design decisions \u2014 a hybrid approach that avoids runtime generation risks."},{"t":"proc-gen","f":"Iterated function systems (IFS) using randomly generated sets of affine transformations can drive particle system visualizations, producing attractor patterns useful for procedural effects and lighting."},{"t":"environment_design","f":"Complex dense environments like Elden Ring's Lindell Capital gate use a strategy of overwhelming scale with soaring towers and intricate filigree detail to convey power and royalty \u2014 the visual density is intentional design language, not random placement."},{"t":"environment_design","f":"Every placement of rocks, broken churches, and cave entrances in Elden Ring is deliberately considered to weave storytelling into the environment geometry itself."},{"t":"workflow","f":"Step 1 of environment recreation in Unreal Engine is gathering reference (images, videos, on-location photos, sketches) using a tool called PureRef to dissect the logic and visual structure before any 3D work begins."},{"t":"environment_design","f":"Large-scale fantasy environments achieve depth and impact through layered visual complexity \u2014 dense intricate surface detail (filigree) combined with macro-scale architectural forms (towers, gates) creates the 'larger than life' effect."},{"t":"marching_cubes","f":"8 corner points per cube, each with a noise value; values above 0 = air/open space, below 0 = rock/solid. 256 possible configurations but only 15 unique cases (rest are symmetries). Surfaces constructed from triangles by connecting edges in groups of 3."},{"t":"density_field","f":"Terrain stored as a 3D texture of scalar values. Zero crossing defines the surface boundary. Negative values = inside solid, positive = open air. Slicing the 3D texture shows lighter regions (outside) and black regions (below surface) with a red boundary line at value 0."},{"t":"marching_cubes_gpu","f":"Core algorithm written in HLSL to process many cubes in parallel on the GPU. Per cube: calculate 8 corner coordinates, look up their density values, determine which of 256 configurations applies via a precomputed triangle table, then find which edges the surface passes through and connect vertices in groups of 3 to form triangles."},{"t":"terraforming_caves","f":"Single-heightmap planets cannot represent caves, tunnels, or overhangs because each point maps to only one height value. A volumetric density field (3D grid of air/rock values) solves this, enabling carving of arbitrary underground geometry."},{"t":"marching_cubes_lookup","f":"A giant precomputed lookup table maps each of the 256 cube configurations to triangle edge connections. Two small arrays map each edge index to its two endpoint corner indices. Vertex placement along each edge defaults to the midpoint for simplicity."},{"t":"planet_noise","f":"Planet terrain generated by starting with a sphere, sampling a 3D noise function at each surface point, and displacing vertices inward/outward based on the noise value. Mixing and layering different noise functions with different equations produces varied terrain."},{"t":"underground_tunnel","f":"Sewer tunnel used as connection path between two building basements; requires blocking out geometry for arch-shaped ceiling and snapping vertices to grid for proper alignment"},{"t":"environmental_storytelling","f":"Sand pouring through drainage grates serves dual purpose: visual storytelling element showing surface proximity and gameplay mechanic providing player entry path into underground space"},{"t":"lighting_underground","f":"Underground spaces require blocking out additional light to sell the illusion of depth; too much ambient light leaking into basement/tunnel areas breaks the underground feel"},{"t":"modular_level_design","f":"Plank boards placed over openings need careful overlap management to avoid z-fighting; thicker board geometry matches concept art and helps sell light occlusion at surface boundaries"},{"t":"tunnel_geometry","f":"Arch-shaped tunnel ceilings require additional subdivided geometry (more geo on the plane) to achieve smooth curved profiles; vertices must sit below the arch curve line to avoid clipping"},{"t":"depth_cue_sightlines","f":"Partial visibility through bars/grates into adjacent spaces creates depth cues and player curiosity; the actual traversal path routes through a different building to reach the visible space"},{"t":"isometric_workflow","f":"For isometric 3D levels, start with a 2D sketch/map before creating a 3D blockout (simple walls, floors, ceilings) in Blender using cube with inverted normals and Ctrl+R loop cuts to extrude walls and cut windows."},{"t":"isometric_workflow","f":"Blender .blend files can be imported directly into Unity without FBX export; Ctrl+S in Blender or Photoshop triggers a live update in Unity, enabling a non-destructive back-and-forth workflow."},{"t":"isometric_workflow","f":"Adding small knife-tool cuts on top of simple boxy meshes makes low-poly stylized art look handmade and intentional, useful for isometric game assets that read well at camera distance."},{"t":"isometric_workflow","f":"Toon/cel shaders (e.g. Toony Colors Pro 2) strip specular, metallic, and normal map complexity, giving isometric scenes a flat stylized look that pairs well with simple geometry and solid color palettes."},{"t":"isometric_workflow","f":"Complex isometric scene objects decompose into primitive shapes: couches = squashed rectangles, tables = squashed cylinders, trees = stacked cones, characters = ovals \u2014 all colored via simple flat material assignments in Blender."},{"t":"city","f":"Road presets include lane configurations with sidewalk variants (e.g., 'two lane + sidewalks'); roads auto-align to landscape with configurable elevation offset and landscape layer masking (e.g., grass removal under roads)."},{"t":"city","f":"Road drawing uses click-to-place nodes for straight segments; holding Shift creates curved segments; middle mouse wheel adjusts elevation in real-time to create bridges and overpasses."},{"t":"city","f":"City kits are swappable asset packs (e.g., 'Modern City', 'Miami Bass') added to a level with one click; custom kits can be created with user-provided meshes and styles."},{"t":"city","f":"Blocks (building zones) are generated using a 'from edges' tool that automatically detects valid buildable areas by analyzing road edge geometry."},{"t":"city","f":"Plugin operates as a custom Editor Mode (Selection Mode > City Builder) with dedicated widget tabs for General, Roads, and Blocks, plus a simplified game-style UI toggle in settings."},{"t":"city","f":"Building props use a struct called 'prop spline points' storing 5 local points that generate a spline path around the building perimeter for fence/edge placement."},{"t":"city","f":"Spline mesh props use two mesh variants: a 'complete mesh' (both sides, used for the last segment) and an 'incomplete mesh' (one side, used for all other segments), with configurable mesh width, tangent length for curvature, and begin/end scale."},{"t":"city","f":"Spline mesh props have a configurable 'percent chance to spawn' (default 75% for fences), a tangent length controlling curvature, and support random material selection from a material list."},{"t":"city","f":"Edge props are individually placed along the building perimeter spline with configurable prop spacing, collision bounds, scale range, rotation, random yaw, and two-tier spawn probability: a global chance (e.g. 20% for pine trees on a house) and per-instance chance (e.g. 100% for each tree if global passes)."},{"t":"city","f":"Road props support spline and edge prop types with specific 'curves and segment settings' unique to roads, and all prop configurations can be loaded from a data table."},{"t":"city","f":"City grid size is controlled by X size and Z size parameters; setting both to 5 with scale 25 creates a walkable city block, while 20x20 at scale 200 generates a full city-scale layout"},{"t":"city","f":"Vertex snapping (V key) is used to align building pieces and prefabs to each other precisely when manually editing the generated city"},{"t":"city","f":"Generated city buildings are composed of individually editable modular pieces (walls, doors, flags) that can be deleted or repositioned post-generation"},{"t":"city","f":"City builder prefab is placed at origin (0,0,0) with initial scale 1,1,1 then scaled up (e.g. 25) to match the terrain size"},{"t":"city","f":"Global volume prefab from postprocesses folder is added for depth/lighting; environment skybox color is customized via Window > Rendering > Lighting panel"},{"t":"city","f":"The tool supports multiple building variations that are randomly selected during generation, providing visual variety across the city grid"},{"t":"city","f":"Road prefabs use a grid step of 38 units for discrete movement, ensuring no gaps form between road segments when snapping"},{"t":"city","f":"Road system height is set to 8.6 units and kept consistent across the entire road network"},{"t":"city","f":"Building block prefabs maintain constant pixel density, border geometry height, and window/floor sizes regardless of shape changes, allowing seamless assembly without UV adjustments"},{"t":"city","f":"Vertex snapping (V key) is used to precisely connect block prefabs to road edges by dragging outermost vertices together"},{"t":"city","f":"Two constructor systems are used: road constructor (Sci-Fi Road Constructor 38 inches folder) and city constructor (Sci-Fi City folder), each containing pre-configured prefabs"},{"t":"city","f":"Linear fog is used for optimization where camera clipping planes far distance and shadow distance match the fog range, and prefabs are marked static to avoid per-frame transforms at runtime"},{"t":"subscene_streaming","f":"Volume-based subscene loading uses two nested volumes: an outer 'preparation' volume for pre-loading scene data into memory, and an inner 'activation' volume that triggers the actual scene load. The activation volume must always be inside the preparation volume or the scene will not load."},{"t":"subscene_unloading","f":"Unload volumes are separate red-box trigger zones placed at exits. By changing 'amount of volumes' and setting type from 'load volume' to 'unload volume', a dedicated unload trigger is created that removes the subscene when the player passes through it."},{"t":"distance_based_loading","f":"Distance-based subscene loading uses a radius from center: the subscene loads when the player enters the range and automatically unloads when the player exits the range. Unlike volume-based loading, there is no separate pre-loading phase, making it optimal only for smaller subscenes."},{"t":"subscene_streaming","f":"Volume-based loading is configured by setting 'subscene loading mode' to 'volume based' in map settings via the subscene cogwheel icon, then setting 'amount of volumes' to define how many load/unload trigger zones exist per subscene."},{"t":"level_chunk_tooling","f":"An eye icon toggle allows hiding subscene geometry so designers can clearly see and position load/unload volumes or distance-based loaders without visual obstruction from the scene content itself."},{"t":"subscene_streaming","f":"Renaming a subscene automatically updates all associated load/unload volumes to reflect the new name, and renaming an entire map triggers a scene reload but preserves all volume configurations. No data is lost during rename operations."},{"t":"uv_unwrap","f":"Always apply scale (Ctrl+A > Scale) before unwrapping; unapplied scale skews UV proportions, distorting texture density across the mesh."},{"t":"uv_unwrap","f":"Use 'Project from View' (UV menu > 3D View > Project from View) as a clean-slate reset before marking seams, to eliminate inherited UV islands and seam artifacts from the modeling process."},{"t":"uv_seam_placement","f":"UV seams should prioritize minimizing distortion over minimizing seam count; place seams at natural geometry breaks (like clothing stitches or material boundaries) rather than trying to reduce them."},{"t":"uv_unwrap","f":"4-step UV workflow: (1) apply scale, (2) project UVs from view, (3) mark seams on edges using Edge mode (press 2) with Alt+Click for edge loops and Ctrl+Click for edge paths, (4) select all faces and unwrap."},{"t":"uv_seam_placement","f":"Triplanar mapping can blend across UV seams for procedural materials, reducing visible seam artifacts without manual texture painting, but should not replace proper unwrapping (avoid relying on cube projection alone)."},{"t":"uv_unwrap","f":"Clean topology with proper edge flow enables Alt+Click loop selection and Ctrl+Click path selection for fast seam marking; poor topology breaks these selection tools and complicates unwrapping."},{"t":"world_generation","f":"Gaia world generation uses a 4-step pipeline: 1) Create World Designer in Gaia Manager, 2) Generate world (stamps island onto terrain), 3) Spawn biomes, 4) Create runtime \u2014 producing a fully populated island"},{"t":"terrain","f":"Gaia stamps pre-generated island heightmaps directly onto Unity terrain, separating world shape generation from biome population"},{"t":"biome_placement","f":"Biome spawning is a distinct automated step that populates terrain with vegetation, textures, and objects after the base terrain is stamped"},{"t":"world_generation","f":"Gaia uses a runtime creation step as the final phase, converting the designed world into a playable game-ready environment"},{"t":"pathfinding","f":"Unity's 3D NavMesh can be repurposed for 2D pathfinding by forcing it into a 2D scaling, avoiding the need to implement A* from scratch."},{"t":"pathfinding","f":"A* pathfinding is the traditional algorithm used for 2D pathfinding when no built-in navigation system is available."},{"t":"navigation_mesh","f":"Unity's NavMesh is natively a 3D system; 2D pathfinding requires either a wrapper/adapter package or a custom A* implementation."},{"t":"pathfinding","f":"For 2D NavMesh pathfinding in Unity, the environment is built using tilemaps with separate layers for ground and walls to define walkable vs non-walkable areas."},{"t":"ai","f":"Enemy state machine uses idle and pursuing states; idle transitions to pursuing when player distance is within search radius AND line-of-sight is true"},{"t":"ai","f":"Line-of-sight (LOS) is checked by calculating the line between enemy and player, then iteratively performing small circular obstacle queries along that line; if the sweep reaches the player unblocked, LOS is true"},{"t":"ai","f":"Pursuit steering uses a direction vector calculated as (player.position - enemy.position).normalize() to always angle movement toward the player"},{"t":"ai","f":"When LOS is lost during pursuing state, a naive fix is to revert to idle, but this causes enemies to give up at corners; a tile-tracking solution assigns pathfinding data to tiles around the player to guide enemies without direct LOS"},{"t":"ai","f":"Distance-radius detection alone lets enemies detect through walls; combining radius check with LOS check fixes wall-penetrating detection so enemies only react when they can actually see the player"},{"t":"ai","f":"State transitions follow the pattern: idle\u2192pursuing (distance < searchRadius AND LOS==true), pursuing\u2192idle (LOS==false as naive fallback), with LOS gating attack actions within pursuing state"},{"t":"navigation_mesh","f":"NavMeshAgent jitter when camera moves can be fixed by disabling automatic position updates (agent.updatePosition = false) in Awake, then manually updating transform.position using Vector3.SmoothDamp in FixedUpdate instead of letting the agent control position directly."},{"t":"steering","f":"Vector3.SmoothDamp provides velocity-based smooth interpolation for character movement, producing smoother results than directly applying NavMeshAgent position updates each frame."},{"t":"navigation_mesh","f":"Movement code for NavMeshAgents should run in FixedUpdate (fixed timestep) rather than Update (variable timestep) when manually controlling transform.position for consistent physics-rate smoothing."},{"t":"animation","f":"Unity animator layers allow splitting animation control by body region \u2014 e.g., a 'base layer' for lower body (legs/locomotion) and an 'upper layer' for upper body (attack/aim), so two animations play simultaneously on different body parts."},{"t":"animation","f":"Unity Avatar Masks define which bones/body parts a layer controls, allowing you to disregard portions of an animation (e.g., exclude legs from an attack clip so only the upper body plays the swing while legs continue the walk cycle)."},{"t":"animation","f":"Animator state machines use boolean parameters (e.g., 'isMoving') for sustained state transitions (idle\u2194sprint) and trigger parameters (e.g., 'attack') for one-shot action transitions, with conditions evaluated on each transition arrow."},{"t":"animation","f":"Without layer-based blending, playing an attack animation interrupts locomotion entirely \u2014 the character stops moving, plays the full attack clip, then resumes walking, creating a visually jarring break in movement."},{"t":"animation","f":"Each Unity animator layer can have its own independent state machine with states and transitions, enabling parallel animation logic (e.g., upper body can be in 'Attack' state while base layer is in 'Sprint' state simultaneously)."},{"t":"blend_tree","f":"A blend tree adaptively changes the transition between two animation states based on input parameters, preventing the delayed or abrupt animations that occur with fixed-duration state machine transitions."},{"t":"blend_tree_setup","f":"A 2D Free Form Directional blend type maps animations onto a 2D parameter space using velocityX and velocityY, where idle=(0,0), run_forward=(0,0.5), and sprint=(0,1.0)."},{"t":"state_machine_transition","f":"State machine transitions use smooth interpolation between two states, but faster transitions reduce smoothness while slower transitions cause animation delay when inputs change rapidly."},{"t":"blend_tree_architecture","f":"Blend trees can replace multiple discrete state transitions; instead of defining boolean-triggered transitions between every animation pair, a single blend tree node handles all locomotion states with continuous parameter control."},{"t":"blend_tree_layering","f":"Additional hard transitions can still be layered on top of blend tree states for actions like direction switching or sprint stopping, combining blend tree smoothness with discrete state changes."},{"t":"animator_controller","f":"Unity's animator controller uses an Entry node that transitions to a default state; blend trees are created as named nodes (e.g., 'player Locomotion') that replace individual animation states in the state machine graph."},{"t":"animation","f":"Motion matching dynamically selects animation frames from a database by analyzing character state, speed, and direction, replacing traditional blend trees and state machines for more fluid movement."},{"t":"animation","f":"Traditional UE animation systems use blend trees and state machines with manually defined transitions based on parameters like speed, direction, and states (idle, walking, jumping), requiring extensive setup and fine-tuning."},{"t":"animation","f":"Motion matching requires configuring pose search schemas, databases, and choosers, plus detailed animation samples with root motion for every action the character needs to perform."},{"t":"animation","f":"Orientation warping and other nodes from the Game Animation Sample (GAS) can be used independently within traditional animation graphs and state machines without adopting full motion matching."},{"t":"animation","f":"For solo or small-team developers wanting full control, traditional animation graphs and state machines are recommended over motion matching due to the complexity and time investment motion matching requires."},{"t":"inverse_kinematics","f":"Inverse kinematics calculates the rotation of all bones in a chain from the tip bone's position, while forward kinematics calculates the tip bone position from the rotation of all other bones in the chain."},{"t":"inverse_kinematics","f":"Two Bone IK constraint is used for anatomically correct characters with standard joint chains (e.g., arm: root=upper_arm, mid=forearm, tip=hand), while Chain IK is used for characters with more bones like rubber-hose style rigs."},{"t":"inverse_kinematics","f":"Two Bone IK constraint requires three bone references: root (upper arm), mid (forearm), and tip (hand), plus two source objects: a target (controls position/rotation) and a hint (controls elbow direction)."},{"t":"inverse_kinematics","f":"The IK constraint weight parameter (0-1) controls how much the rig is affected by the constraint; setting weight to 1 means full IK control, and dynamically changing weight in code allows switching between multiple IK rigs (e.g., hand-on-object vs hand-on-terrain)."},{"t":"inverse_kinematics","f":"The 'auto setup from tip's transform' option in Unity's Animation Rigging automatically creates target and hint game objects for the IK constraint, positioned relative to the tip bone."},{"t":"inverse_kinematics","f":"The IK target object should be aligned to the hand bone's transform using 'align transform' (select target then ctrl+click hand), and a rig setup requires both a Bone Renderer (for bone visualization/selection) and a Rig component as parent of IK constraints."},{"t":"animation","f":"Attack combos use an Animation Montage array variable on the Third Person Blueprint, sized to the number of combo attacks (e.g., 3), with each montage assigned to a corresponding array index."},{"t":"animation","f":"A boolean variable tracks whether the character is currently in an attack animation, and a separate integer variable tracks the current attack index in the combo array to sequence through montages."},{"t":"animation","f":"Play Montage node (not Play Animation Montage) is used with the skeletal mesh component; it checks the attack bool before playing and resets it on montage end via the On Completed callback."},{"t":"animation","f":"Combo progression logic increments the attack index each attack; if the index reaches the array length the combo resets to index 0, otherwise it advances to the next montage in the array."},{"t":"animation","f":"Input buffering for combos is implemented by adding an Anim Notify named 'CanAttack' at a specific frame in each Animation Montage, marking the earliest point the player can queue the next attack."},{"t":"animation","f":"In the Animation Blueprint (ABP) Event Graph, the CanAttack Anim Notify is received, cast to the Third Person Character, and sets the attack boolean to false \u2014 reopening the input window for the next combo hit."},{"t":"animation","f":"Animation Rigging creates a secondary rig layer that overrides specific bones of the original animation at runtime, allowing dynamic control without modifying the base animation clip."},{"t":"animation","f":"Character animation pipeline follows three steps: animator determines which animation plays, bones are moved by that animation, then the Skinned Mesh Renderer deforms the mesh to follow the bones."},{"t":"IK","f":"The Multi Aim Constraint references a target bone (e.g., head) and a target transform object, overriding that bone's rotation at runtime to track the target while the base animation continues playing."},{"t":"animation","f":"The character skeleton (rig) is a hierarchy of GameObjects representing bones: pelvis \u2192 spine \u2192 thigh \u2192 calf \u2192 foot, stored as children of the base object alongside the mesh."},{"t":"animation","f":"A standard animated character in Unity consists of three parts: a base GameObject with an Animator component, a child mesh with a Skinned Mesh Renderer, and a bone hierarchy (rig) as child GameObjects."},{"t":"animation","f":"Animation Rigging constraints allow runtime interaction (picking up objects, aiming, placing hands/feet on environment) by overriding specific bones without requiring pre-baked animation clips for every scenario."},{"t":"root_motion","f":"Root motion glues the capsule collision to the character mesh for the duration of an animation, preventing the character from moving outside the capsule collision during attacks or movements."},{"t":"root_motion","f":"Root motion requires the character to be moved by the root bone in the source animation; in Blender, ensure the root bone drives all character translation."},{"t":"root_motion","f":"In Unreal Engine, enable root motion by selecting the animation asset, searching 'root' in the detail section, and ticking 'Enable Root Motion'. A red line from center point to character in viewport (Character > Bones > All Hierarchy) confirms root bone movement is present."},{"t":"root_motion","f":"If the character moves into a funny angle when root motion is enabled, set 'Root Motion Root Lock' to 'Anim First Frame' to fix orientation issues."},{"t":"animation_montage","f":"To use root motion at runtime, convert the root motion animation to a Montage (right-click animation in Content Browser > Convert to Montage), then play the Montage from the character blueprint. A default slot must be configured in the Animation Blueprint."},{"t":"root_motion","f":"Root motion is recommended for specific actions like weapon attacks rather than basic locomotion (walk/run), since standard capsule-driven movement is more appropriate for general movement."},{"t":"state_machine","f":"A start-to-walk and walk-to-stop system can be built entirely in the animation blueprint using state machines, without needing to play montages manually."},{"t":"root_motion","f":"The start-to-walk animation requires root motion enabled so the animation itself drives the character's forward movement when transitioning from idle to walking."},{"t":"state_machine","f":"A boolean variable 'has_movement_input' is set true on key press and false on key release (WASD), and is used as the primary transition condition between idle, walk-start, walking, and walk-stop states."},{"t":"transition","f":"Eight directional movement possibilities exist (forward, back, left, right, and four diagonals), each requiring a unique start-to-walk animation and direction calculation to select the correct transition."},{"t":"state_machine","f":"State machine complexity for directional locomotion can be reduced by using variables inside states and state transition rules rather than duplicating logic across many transition lines."},{"t":"transition","f":"A quick tap of the movement key triggers both start-to-walk and walk-to-stop animations in rapid sequence, requiring the state machine to handle very short input durations gracefully."},{"t":"root_motion","f":"Enable root motion for start/stop locomotion animations by bulk editing via Property Matrix: check 'Enable Root Motion' and 'Force Root Lock' on all start/stop animation assets."},{"t":"state_machine","f":"Locomotion state machine uses three distinct states for directional movement: Movement Start, Cycle (looping walk/jog), and Stop, each requiring their own orientation warping node configuration."},{"t":"animation","f":"Orientation warping nodes require spine bone references matching the target skeleton; UE5 mannequin has 5 spine bones while UE4 mannequin has 3, causing errors when retargeting that must be fixed by deleting and re-adding the correct spine bone count."},{"t":"animation","f":"Start and stop animations are created per direction (forward, backward, left, right) as separate assets, paired with corresponding cycle (looping) animations for each movement direction."},{"t":"animation","f":"Retargeting an animation blueprint via 'Retarget Animation Assets > Duplicate and Retarget Animation Blueprint' automatically retargets all animations already slotted in the animation blueprint's state machine groupings."},{"t":"animation","f":"Orientation warping nodes must be configured in every state of the locomotion state machine (start, cycle, stop); missing or misconfigured nodes cause the character to face forward regardless of movement direction."},{"t":"animation_blend_tree","f":"In Godot 4, an AnimationTree node with a BlendTree root allows smooth transitions between animations by using Blend2 nodes, where a blend_amount value of 0.0 means fully first animation and 1.0 means fully second animation."},{"t":"state_machine_blend","f":"Multiple Blend2 nodes can be chained in series (idle\u2192run\u2192sit\u2192jump\u2192output) so that whichever blend value is highest transitions from the base idle pose to that animation, with all-zero values passing idle through every blend."},{"t":"animation_transition","f":"Smooth blending between animation states is achieved by interpolating blend values using lerp_f(current_value, target, blend_speed * delta), with a typical blend_speed of 15 providing responsive transitions."},{"t":"animation_blend_tree","f":"AnimationTree blend parameters are set via anim_tree.set('parameters/<blend_node_name>/blend_amount', value), where blend node names like 'run', 'jump', 'sitting' correspond to the named Blend2 nodes in the tree."},{"t":"state_machine","f":"An enum defining states (IDLE, RUN, SIT, JUMP) combined with a current_animation variable drives a switch statement in handle_animations(delta) that determines which blend values to lerp toward 1.0 or 0.0 each frame."},{"t":"animation_blend_tree","f":"Blend2 node values can exceed the 0-1 range to produce exaggerated or interesting animation effects, though normal usage keeps values clamped between 0.0 and 1.0."},{"t":"root_motion","f":"Root motion animations move the character by animating the root bone (first/top bone in skeleton hierarchy), which translates the character's position in world space rather than animating in place."},{"t":"root_motion","f":"In Unreal Engine, root motion must be explicitly enabled on the animation asset \u2014 without enabling 'Enable Root Motion' in the animation file, the animation plays in-place and the capsule/character does not move."},{"t":"animation_montage","f":"Root motion animations are typically played via Animation Montages in UE \u2014 created by right-clicking the animation asset and selecting 'Create AnimMontage', then triggered in Blueprint with 'Play Montage' node specifying play rate (1.0), starting position (0), and the skeletal mesh component."},{"t":"IK_root_motion","f":"When moving the root bone forward in a root motion animation, IK targets do not automatically follow \u2014 all bones including IK targets must be selected and moved together, then keyframed with location+rotation to maintain correct IK solving."},{"t":"animation_export","f":"When exporting root motion animations from Blender for UE using Mr Mannequin FBX exporter, use 'Actions' export mode with sample rate of 1 (not 'Start End Keyframes') to properly capture the root bone translation data."},{"t":"animation_keyframing","f":"For root motion authoring in Blender: enable auto-keyframe, select all bones (A), set keyframes with I > Location Rotation at start frame, then at target frame (e.g. frame 30) move entire skeleton forward and set location+rotation again for all bones."},{"t":"state_machine_transition","f":"In Godot's AnimationTree, setting the 'advance expression base node' to the CharacterBody3D allows state machine transitions to automatically evaluate character properties (like velocity) without code, using expressions in the transition's 'advance > expression' field."},{"t":"transition_expression","f":"A state machine transition expression 'velocity.length() > 0.2' on the idle-to-run transition triggers the run animation when the CharacterBody3D moves with any magnitude above 0.2."},{"t":"transition_weight","f":"A cross-blend value of 0.2 seconds is used on the idle-to-run transition for smooth blending between animation states in Godot's AnimationTree state machine."},{"t":"state_machine","f":"A basic character animation state machine in Godot uses three states \u2014 idle (loop), run (loop), and fall (loop) \u2014 as the foundational locomotion setup, managed via AnimationTree with a state machine root."},{"t":"locomotion","f":"Tank-style locomotion (forward/backward movement with left/right rotation) is implemented by zeroing out the X input direction and instead applying input to rotation: 'rotation.y -= input_dir.x * deg_to_rad(some_value)' to rotate the character."},{"t":"animation","f":"Godot's animation retargeting workflow involves clicking the skeleton, adding a new BoneMap set to 'Humanoid', mapping bones, and reimporting \u2014 then using 'Editable Children > Animation Player > Manage Animations > Load Library' to assign an animation library."},{"t":"root_motion","f":"Root motion drives character movement from the animation itself rather than code; the armature is animated moving through space, and the engine extracts translation/rotation deltas per frame to move the character, ensuring in-engine movement matches the animation software exactly."},{"t":"locomotion","f":"Root motion locomotion preserves per-step speed variation (acceleration, deceleration, stop-starts) baked into the animation clip, unlike scripted movement which typically applies a constant speed with a looping walk cycle played on the spot."},{"t":"blend_tree","f":"Pivoting to arbitrary angles is achieved by blending between a 90-degree turn animation and a 180-degree turn animation in a blend tree; interpolating the blend weight produces smooth pivot movements to any angle between those extremes."},{"t":"foot_placement","f":"Root motion eliminates foot sliding by tying character displacement directly to the animated foot-contact positions; blending a forward-walk clip with a walk-and-turn clip keeps feet planted correctly during directional changes, unlike scripted rotation which causes skate/slide artifacts."},{"t":"transition","f":"Root motion is recommended only when the game heavily focuses on exaggerated movement animations, realistic pivots, or complex character-specific motion patterns; otherwise scripted movement with standard animation blending can achieve visually comparable results with far less animator-programmer coordination overhead."},{"t":"animation","f":"In Blender, root motion clips are authored by translating the armature root bone through world space as part of the keyframed animation, rather than animating a walk cycle in place; the resulting clip encodes both pose and displacement data for the engine to consume."},{"t":"root_motion_navmesh","f":"Root motion with NavMeshAgent requires implementing the OnAnimatorMove callback to synchronize the root motion position with the NavMeshAgent's nextPosition, preventing the animator and agent from fighting over character movement."},{"t":"blend_tree_locomotion","f":"Animator setup requires velocity X and velocity Y parameters for a 2D blend tree, or a single Locomotion parameter for a 1D blend tree, with states for run forward, run backwards, run left, run right, and run 90 degrees."},{"t":"blend_tree_idle_trick","f":"In a 1D locomotion blend tree, using a slow walking animation instead of an idle animation at the zero-speed threshold produces better results with root motion NavMeshAgent synchronization."},{"t":"root_motion_benefit","f":"Root motion eliminates foot sliding because character displacement comes directly from the animation data rather than from a character controller or NavMeshAgent speed value that may not match the animation's actual movement speed."},{"t":"navmesh_root_motion_update_loop","f":"The update loop sets animator parameters (velocity X/Y or locomotion) based on the NavMeshAgent's current movement direction and desired velocity, while OnAnimatorMove synchronizes positions each frame after the animator evaluates."},{"t":"blend_tree_dimensions","f":"Both 2D blend trees (using velocityX + velocityY) and 1D blend trees (using a single locomotion float) can drive root motion NavMeshAgent animation with the same synchronization script, requiring only different animator parameter setups."},{"t":"root_motion","f":"To verify root motion in an animation, open the animation asset, go to Skeleton Tree, click on the root bone \u2014 a visible translation line from start to end position confirms root motion data exists."},{"t":"root_motion","f":"In UE5, enable root motion by opening the animation asset, going to Asset Details, scrolling to Root Motion section, and checking 'Enable Root Motion' \u2014 the preview will appear in-place, which is expected behavior."},{"t":"root_motion","f":"Root motion can be applied through two methods: playing the animation inside an Animation Montage (via Play Montage node), or enabling it directly inside the Animation Blueprint."},{"t":"ik_retargeting","f":"When retargeting animations that contain root motion using UE5's IK Retargeter, set the root chain's Translation Mode to 'Globally Scaled' in the Chain Mapping settings to preserve root motion data."},{"t":"animation","f":"To create a montage from an animation with root motion: right-click the animation asset \u2192 Create \u2192 Animation Montage. The montage can then be triggered in a Character Blueprint using the Play Montage node."},{"t":"animation","f":"Animations labeled 'in place' in asset packs are versions without root motion, while their counterparts without that label contain root motion translation data on the root bone."},{"t":"root_motion","f":"Root motion moves the character via the animation itself rather than script, producing correct foot positions during walk/run and precise movement during attacks, eliminating foot sliding."},{"t":"root_motion","f":"Enable root motion by selecting 'Apply Root Motion' checkbox on the Animator component; the animation's embedded translation/rotation then drives the GameObject's movement each frame."},{"t":"root_motion","f":"For child-object animators, implement OnAnimatorMove() to manually apply animator.deltaPosition and animator.deltaRotation to the parent Rigidbody via MovePosition and MoveRotation, making the Animator show 'Handled by Script'."},{"t":"root_motion","f":"In humanoid rig import settings, configure Root Transform Rotation, Root Transform Position (Y for height), and Root Transform Position (XZ for movement) to control how root motion influences rotation, height, and lateral movement."},{"t":"root_motion","f":"Set Root Transform Rotation to 'Bake Into Pose' (Based Upon: Original) to strip unwanted left/right rotation drift from a forward walk animation, preventing unpredictable facing-direction changes when stopping mid-animation."},{"t":"blend_tree","f":"A Blend Tree driven by a 'speed' float parameter blends idle/walk/run clips; a script sets the speed value, and enabling 'Apply Root Motion' lets the blended animation's root motion drive the character's actual movement speed."},{"t":"locomotion","f":"Use ForceMode.VelocityChange when adding force to a rigid body player controller \u2014 this ensures velocity changes are not affected by the rigid body's mass or the simulation step length."},{"t":"locomotion","f":"Apply high drag only while the player is grounded and low drag while airborne; failing to switch causes floating/gliding when walking off edges."},{"t":"locomotion","f":"Ground checking via simple raycast fails on edges; use sphere cast or OnCollisionEnter, then validate the hit is ground by checking the slope angle (angle between player down vector and surface normal) against a threshold."},{"t":"locomotion","f":"Character controller can interact with Unity physics by applying a force at each contact point in the direction of the surface normal on every rigid body collision."},{"t":"locomotion","f":"Directly setting rigid body velocity every physics frame is discouraged by Unity docs because it breaks the physics simulation \u2014 forces should be used instead."},{"t":"locomotion","f":"Physics code must go in FixedUpdate to sync with Unity's fixed-rate physics simulation; wall collisions can falsely register as ground, fixable by assigning ground objects to a separate physics layer or checking slope angle."},{"t":"audio","f":"Resonance Audio plugins in FMOD + Unity provide full 3D spatialized sound with perceptible front/back, left/right, and up/down positioning; headphones required for proper perception."},{"t":"audio","f":"Audio occlusion can be implemented by casting multiple raycasts (triangulated lines) from around the listener to the audio source, counting how many are blocked by physical game objects, and using the green-to-red (unobstructed-to-obstructed) percentage to drive an occlusion filter parameter in FMOD."},{"t":"audio","f":"Audio occlusion modifies both amplitude and frequency content of the sound when a wall or object obstructs the path between source and listener, simulating real-world muffling."},{"t":"audio","f":"Vertical raycasts should be included in the occlusion system so that player jumps dynamically affect the occlusion percentage, changing audio filtering in real time based on vertical position changes."},{"t":"audio","f":"A spherical AudioSource emitter (green sphere in scene) serves as the 3D spatialized sound origin; the occlusion system visualizes unobstructed rays as green and obstructed rays as red in the Unity scene view for debugging."},{"t":"audio","f":"Spatial audio in Wwise uses three primary tools: Rooms (represent acoustic environments for both outdoor and indoor spaces), Portals (small rectangular apertures connecting rooms through which sound propagates or diffracts), and Reverb Zones (regions within a room with distinct reverb that don't require portals, used where there are no obvious walls like an external patio)."},{"t":"audio","f":"Spatial audio volumes in Unreal/Wwise require enabling: Room, Late Reverb, Surface Reflector Set, Enable Diffraction, and Enable Diffraction on Boundary Edges for full spatial audio with reflections and diffraction."},{"t":"audio","f":"Spatial audio volumes have a 'Fit to Geometry' option that automatically conforms the volume shape to the surrounding room geometry, after which it can be unticked to lock the shape."},{"t":"audio","f":"Each face of a spatial audio volume can be assigned individual acoustic textures (e.g., concrete on walls, carpet on floor) and a per-wall transmission loss percentage controlling how much sound passes through that specific surface."},{"t":"audio","f":"Wwise spatial audio requires creating auxiliary buses (e.g., Reverb Large, Reverb Small, Reverb Patio) with reverb effects (such as convolution reverb), adding them to the sound bank, generating the bank, then reconciling new assets in the engine."},{"t":"audio","f":"Wwise spatial audio manages game object properties including position, auxiliary sends, obstruction, occlusion, and transmission, and runs geometric reflection, diffraction, and transmission algorithms packaged for the Reflect plug-in."},{"t":"audio","f":"AudioSettings.dspTime returns a double representing the precise number of samples processed by the audio system, independent of frame rate, making it far more accurate than Time.time or WaitForSeconds for audio timing."},{"t":"audio","f":"AudioSource.PlayScheduled(goalTime) plays a clip at an exact DSP time rather than immediately, enabling sample-accurate scheduling by setting goalTime = AudioSettings.dspTime + delay."},{"t":"audio","f":"Clip duration in seconds can be calculated by dividing clip.samples by clip.frequency, then used to compute the exact DSP time when the clip will finish: nextGoalTime = currentGoalTime + (clip.samples / clip.frequency)."},{"t":"audio","f":"Calling PlayScheduled on an AudioSource stops whatever clip is currently playing on that source, so seamless back-to-back playback requires two AudioSources that alternate (double-buffering pattern) toggling an index between 0 and 1."},{"t":"audio","f":"When using PlayScheduled, the next clip should be pre-loaded and scheduled slightly before the current clip ends (e.g., goalTime - 1 second) rather than at the exact finish time, to avoid late scheduling artifacts."},{"t":"audio","f":"For scheduled AudioSources, looping and Play On Awake must both be disabled in the inspector, as they interfere with manual PlayScheduled timing and cause playback problems."},{"t":"audio","f":"Adaptive audio means sound changes dynamically based on game state: volume increases as player approaches a location (distance attenuation), heartbeat intensity scales with health, and footstep sounds vary by surface material."},{"t":"audio","f":"In FMOD, each piece of audio the game needs to play is created as an 'event' \u2014 an event can be a single sound or a collection of sounds with varying effects and internal logic, and events can be parameterized so sound varies based on parameter values."},{"t":"audio","f":"For footstep events, FMOD can contain multiple sound clips each representing a slightly different footstep, with internal logic that randomly selects which clip to play each time \u2014 preventing repetitive audio."},{"t":"audio","f":"FMOD provides distance-based volume attenuation where sounds play louder as the player gets closer to a specific location, implementing spatial 3D audio behavior through its event system."},{"t":"audio","f":"FMOD has direct integration plugins for Unity, Unreal Engine 4, and Unreal Engine 5; other engines like Godot can integrate via the FMOD Engine Runtime API or community-made integration plugins."},{"t":"audio","f":"FMOD events can be parameterized, allowing a single event's sound output to vary dynamically based on parameter values passed from the game engine \u2014 enabling ambient triggers and context-sensitive audio without creating separate audio sources."},{"t":"ambient_zone_system","f":"Divide map into ambient zones using trigger colliders (one per area). Create an empty GameObject, add a collider component, set isTrigger=true, then size/position each collider to cover its area (forest, grassland, etc.)."},{"t":"ambient_crossfade_gap","f":"Leave a gap between adjacent ambient zone colliders \u2014 the gap space is where crossfading occurs. The fade distance is controlled by each sound's distance attenuation settings, so the gap width should match the desired crossfade range."},{"t":"floating_sound_proximity","f":"Create a 'floating sound' script: store a reference to the zone collider and the player transform. In Update(), call collider.ClosestPoint(player.position) and set the AudioSource's transform.position to that returned point. The sound always sits at the nearest edge of the zone to the player."},{"t":"proximity_vs_trigger_transitions","f":"Trigger-based (OnTriggerEnter/Exit) ambient transitions are time-based and ignore player movement after firing \u2014 if a player stops mid-transition, the fade completes anyway. Proximity-based systems (ClosestPoint + distance attenuation) react continuously to player position, producing natural real-world-like blending."},{"t":"3d_audio_distance_attenuation","f":"The crossfade between ambient zones is entirely driven by each AudioSource's distance attenuation curve \u2014 no manual volume scripting needed. As the floating sound's ClosestPoint moves farther from the player (outside the zone), the engine's rolloff naturally fades it out."},{"t":"custom_collider_shapes","f":"For ambient zones that can't be covered by Unity's basic geometry colliders (Box, Sphere, Capsule), use MeshColliders or composite colliders to create custom-shaped ambient zones that still support ClosestPoint() queries."},{"t":"audio","f":"AudioSource.Play() fails when the GameObject is destroyed mid-playback \u2014 if an enemy dies and its GameObject is destroyed, the AudioSource is destroyed too and the final sound clip won't play."},{"t":"audio","f":"AudioSource.PlayClipAtPoint(clip, transform.position, volume) temporarily creates a hidden GameObject with an AudioSource, plays the clip, then auto-destroys \u2014 but you cannot assign an AudioMixer output to it."},{"t":"audio","f":"Unity AudioMixer groups let you route sound categories (music, SFX) to separate channels, apply effects per group, and control volume via UI sliders by exposing mixer parameters."},{"t":"audio","f":"A Singleton SoundEffectsManager pattern solves both problems: it persists independently of game objects being destroyed and allows assigning an AudioMixer output to its AudioSource for volume control."},{"t":"audio","f":"AudioSource.PlayClipAtPoint accepts three parameters: AudioClip, Vector3 worldPosition, and float volume (0-1), providing basic spatial 3D audio playback at a specific point."},{"t":"audio","f":"Always uncheck 'Play On Awake' on AudioSource components when you want programmatic control over when sounds play, otherwise clips will trigger automatically when the GameObject initializes."},{"t":"audio","f":"Sound effects that need reverb must be converted to an Audio Cue, with 'Override Attenuation' enabled and 'Enable Reverb Send' ticked in the attenuation settings."},{"t":"audio","f":"A Reverb Effect asset is created via right-click > Sounds > Effects > Reverb Effect, and the 'Decay Time' parameter controls perceived room size \u2014 larger values (e.g., 15\u201320) simulate large caves, smaller values simulate small rooms like bathrooms."},{"t":"audio","f":"Without reverb, a sound plays 'flat' with no echo; enabling reverb send on the audio cue and placing it in a reverb zone adds realistic echo and spatial depth."},{"t":"audio","f":"Each audio cue that needs reverb must be individually configured \u2014 override attenuation and enable reverb send are per-cue settings, not global."},{"t":"audio","f":"Multiple Reverb Effect assets can coexist in a project \u2014 e.g., one for a cave (Decay Time ~15-20), one for a bathroom, one for a tunnel \u2014 each with distinct parameter tuning for that environment type."},{"t":"audio","f":"Animation Events (blue arrow markers on the timeline) allow syncing audio playback to exact frames in an animation clip, preventing sounds from playing too early when using AudioSource.Play() directly."},{"t":"audio","f":"To add an animation event: select the GameObject, open the Animation window, choose the target animation clip, position the playhead at the desired time, and click the 'Add Event' button to insert a callback marker."},{"t":"audio","f":"Animation events call public void methods on scripts attached to the same GameObject; the function must be public (e.g., 'public void PlaySound() { audioSource.Play(); }') and the GameObject must have both the script and an AudioSource component."},{"t":"audio","f":"If no script is attached to the GameObject, the animation event function dropdown will be empty \u2014 a MonoBehaviour script with at least one public method must be added before animation events can trigger audio."},{"t":"audio","f":"Game audio integration sits between audio/music production and game design \u2014 the core workflow is integrating audio and music into a game engine, not producing the audio itself."},{"t":"audio","f":"Modern game audio workflows use audio middleware (like Wwise) as an intermediary between a DAW and the game engine, rather than importing audio directly into the engine."},{"t":"audio","f":"Steinberg Nuendo DAW has a 'Game Audio Connect' feature that bridges the DAW directly to game engines, enabling tighter integration between audio production and in-engine playback."},{"t":"audio","f":"Game audio integration workflows are designed to be game-engine-agnostic and DAW-agnostic, meaning the spatial audio concepts (distance attenuation, reverb zones, triggers) apply across Unity, Unreal, and other engines."},{"t":"audio","f":"Sound occlusion through walls requires enabling 'override attenuation' on the sound source and setting distance falloff values (e.g., inner radius 150, outer radius 1000), then enabling 'enable occlusion' to muffle or block sound through geometry."},{"t":"audio","f":"Occlusion volume attenuation controls how much sound passes through walls: 0.0 = completely silent behind walls, 0.2 = muffled but audible, 1.0 = no occlusion effect (full volume passes through)."},{"t":"audio","f":"When a sound is occluded and volume drops to zero, the audio source stops playing by default; setting virtualization mode to 'Play When Silent' keeps the sound playing even when inaudible so it resumes naturally when the listener returns."},{"t":"audio","f":"Sound occlusion uses level geometry (walls, doors) as occluders automatically once enabled \u2014 no special collision volumes or trigger zones are needed for basic wall occlusion."},{"t":"audio","f":"Distance attenuation and occlusion are separate systems: attenuation controls volume falloff over distance (inner/outer radius), while occlusion handles volume reduction when geometry blocks the line of sight between listener and source."},{"t":"audio","f":"Sound Cues (sound queues) wrap raw audio assets and allow adding attenuation and occlusion properties; these properties are configured on the cue rather than individual sound files."},{"t":"audio","f":"To add audio in Unity, create an empty GameObject, add an AudioSource component via Add Component in the Inspector, then drag an audio clip into the AudioSource's audio clip field. Play On Awake is checked by default so it plays when the scene starts."},{"t":"audio","f":"To loop audio in Unity, enable the Loop checkbox on the AudioSource component. To adjust volume and pitch, use the Volume and Pitch sliders on the AudioSource (e.g., volume set to 0.6 to reduce loudness)."},{"t":"audio","f":"AudioSource Priority determines how an audio source competes with others; higher priority sources are heard louder over lower priority ones when multiple AudioSources play simultaneously."},{"t":"audio","f":"To persist audio across scene loads, use DontDestroyOnLoad(this.gameObject) in the Awake() method of a script attached to the music GameObject. Awake runs before Start, ensuring persistence is set before the scene fully loads."},{"t":"audio","f":"A singleton pattern is needed for persistent audio: DontDestroyOnLoad prevents destruction, but each scene reload instantiates a new music GameObject, causing duplicate audio. The script must check for and destroy duplicates."},{"t":"audio","f":"To crossfade music at runtime, use two AudioSources: one with PlayOnAwake and Loop enabled at target volume, the other with Loop enabled and volume set to zero. Swap roles when triggered."},{"t":"audio","f":"Smooth volume crossfade uses a coroutine with a percentage tracker: start at 0, increment by Time.deltaTime / transitionTime each frame, lerp volume from defaultVolume to 0 for outgoing and 0 to defaultVolume for incoming."},{"t":"audio","f":"To allow interrupting a crossfade, call StopAllCoroutines() before starting the new crossfade coroutine; without this, multiple overlapping coroutines will conflict."},{"t":"audio","f":"The crossfade coroutine first pauses the currently playing AudioSource, unpauses the target, and calls Play() on the target if it wasn't already playing, then runs two sequential while-loops for fade-out and fade-in."},{"t":"audio","f":"A boolean flag tracking which AudioSource is currently playing can be used to correctly identify and swap the active and target sources, toggling after each transition."},{"t":"audio","f":"Spatial audio integration in Unity involves posting events via game-defined callbacks, managing sound bank loading/unloading, and configuring reverb zones to emulate acoustic environments."},{"t":"audio","f":"Reverb zones are used to emulate room acoustics by subscribing game objects to specific acoustic environments, replacing static reverb with spatially-aware acoustic processing."},{"t":"audio","f":"Wwise spatial audio integration uses 'rooms and portals' architecture where game objects subscribe to acoustic environments, enabling dynamic reverb and distance-based attenuation without manual per-source configuration."},{"t":"audio","f":"Spatial audio in Unity game integration requires three layers: event posting via callbacks on AudioSource-equivalent objects, sound bank loading for asset management, and environment subscription for acoustic context."},{"t":"audio","f":"Unity Timeline audio tracks can play sound without an AudioSource component assigned, but an AudioSource is needed for 3D spatial sound emission from a specific position or to apply effects like reverb and low pass filters."},{"t":"audio","f":"The low pass filter effect on an AudioSource is used to simulate a character being stunned or underwater by lowering the cutoff frequency, which muffles higher frequencies."},{"t":"audio","f":"AudioSource pitch can be adjusted (e.g., set to 1.1) to create slight variation in repeated sound effects like explosions, preventing repetitive identical playback."},{"t":"audio","f":"To emit 3D spatial sound from a specific world position, attach an AudioSource component to a GameObject at that location and assign it to the Timeline audio track."},{"t":"audio","f":"Ambient audio volume in Unity Timeline is controlled by selecting the audio track and adjusting the volume property, e.g., reducing to ~0.5 to keep it as background."},{"t":"audio","f":"Timeline audio clips can be split at the playhead position using the 'S' key shortcut, then trimmed or stretched to match animation timing of other tracks like activation tracks."},{"t":"combat","f":"Parry system uses two types: passive parry (automatic deflection when weapon is held in guard stance near incoming strike) and active parry (player manually flicks weapon to intercept an incoming attack). No dedicated block button exists."},{"t":"combat","f":"Passive parry only activates when the weapon is held in a neutral guard stance in front of the character. It deactivates when the weapon is raised too high, extended out for a swing, or otherwise out of guard position."},{"t":"combat","f":"Stance system ties foot position to weapon side: weapon angled to the right puts right foot forward, moving weapon to the left switches to left foot forward. Stance affects defensive vulnerability, particularly hand exposure."},{"t":"combat","f":"Sprint key (shift) lowers the character into an athletic crouch stance enabling dodging and fast movement. It consumes stamina but is recommended to be held frequently during combat."},{"t":"combat","f":"Mouse sensitivity should be set very low (example: middle of slider at 800 DPI) for precise weapon control. High sensitivity causes erratic flailing with no tactical precision."},{"t":"combat","f":"Optimal defense combines three layers: passive parry (guard stance auto-deflection), active parry (manual flick interception), and dodge/footwork movement to avoid strikes entirely."},{"t":"combat","f":"Attack combos use a boolean variable to track if character is in attack animation, an Animation Montage array variable sized to combo length (e.g., 3 for a 3-hit combo), and an integer variable tracking the current attack index in the array."},{"t":"combat","f":"Combo logic: on attack input, check if not already attacking, then play current montage from array. On animation end, reset attacking boolean. Increment combo index each attack; if index reaches array length, reset to 0 for next press."},{"t":"combat","f":"Input buffering for combos is implemented by adding an Animation Notify named 'can attack' at a specific frame in each Animation Montage, marking the point where the player can buffer their next attack input."},{"t":"combat","f":"The 'can attack' notify is handled in the Animation Blueprint (ABP) event graph: on receiving the notify, cast to the third person character and set the attack boolean to false, allowing the next attack input to register."},{"t":"combat","f":"Play Montage node (not Play Animation Montage) is used for combo systems, referencing the skeletal mesh component, and replaces the simpler play-and-montage approach from single attacks."},{"t":"combat","f":"Animation Notifies can be copied from one Animation Montage and pasted into others at desired frames, allowing consistent combo buffer timing across all attacks in the chain."},{"t":"combat","f":"Three-hit combo system with ability to flip/change direction mid-combo, allowing the player to re-orient attacks between hits"},{"t":"combat","f":"Attack movement nudges the character forward in their facing direction on hit, and the left stick up/down moves the character on the z-axis while attacking"},{"t":"combat","f":"Action caching system stores the next player input (e.g. attack after dash) during a current animation and executes it immediately when the current animation ends, preventing perceived input eating"},{"t":"combat","f":"Hitbox z-axis size in 2.5D requires careful tuning via trial-and-error against a dummy NPC to avoid frustrating whiffs where attacks visually appear to connect but miss"},{"t":"combat","f":"Knockback pushes the enemy in the opposite direction of the player on hit, including diagonal pushback along the z-axis, providing satisfying hit feedback"},{"t":"combat","f":"Hit reactions are applied to both player and NPC \u2014 the NPC receives damage and plays hit reaction animations, and the player also reacts to being hit by AI attacks"},{"t":"combat","f":"Melee combat input detection uses UserInputService.InputEnded event, checking for UserInputType == Enum.UserInputType.MouseButton1 to trigger punch attacks on left click."},{"t":"combat","f":"A combo system requires a cooldown mechanism to prevent spam-clicking, implemented alongside a combo counter that tracks sequential hits."},{"t":"combat","f":"Combat architecture uses a client-server split: a LocalScript ('combat client') detects input and fires a RemoteEvent, while a server Script ('server combat') listens via OnServerEvent to process hits and damage."},{"t":"combat","f":"Input guard pattern: check if the input event's gameProcessedEvent parameter is true (variable 'e') and return early, preventing combat actions from firing while the player is typing in chat."},{"t":"combat","f":"Hit VFX (visual effects) are separate assets imported into the game, attached to play on punch impact to give visual feedback for melee strikes."},{"t":"combat","f":"The RemoteEvent is created in ReplicatedStorage (named 'MainEvent') and fired from client via FireServer(), with the server listening via OnServerEvent:Connect(function(player) ...) to process combat actions."},{"t":"combat","f":"Melee hitbox is implemented as a box collision component attached to the character, with box extent and location adjusted to match the attack animation's reach. For beat-em-ups with multiple lanes, the hitbox depth controls how far attacks reach into other lanes."},{"t":"combat","f":"Hitbox collision preset is set to Custom with all channels set to Ignore, then only Pawn set to Overlap, ensuring the hitbox only detects characters and not other objects."},{"t":"combat","f":"A hit_check function uses GetOverlappingActors on the hitbox with a class filter, iterates with a ForEach loop, skips self (since the hitbox overlaps the owner), and calls ApplyDamage on each other actor. A damage amount variable controls per-attack damage."},{"t":"combat","f":"An is_attacking boolean is set true on attack input and false when the attack flipbook finishes playing. On Tick, hit_check is only called when is_attacking is true, but this causes multiple damage applications per attack since it fires every frame."},{"t":"combat","f":"Attack animation uses a non-looping flipbook. Set Looping is called with false on attack start. The OnFinishPlaying event fires when the animation completes, which resets to idle flipbook, re-enables looping, and calls Play if the sprite has stopped."},{"t":"combat","f":"The AnyDamage event on the receiver is triggered by ApplyDamage and provides the received damage value. The hitbox can be visualized by toggling SetHiddenInGame to false when is_attacking is true and back to true when the attack ends."},{"t":"combat","f":"Each weapon has a limited number of efficient dodges; after exceeding this count, dodge distance shrinks progressively. Efficient dodges reset after 0.5 seconds of not dodging, so optimal dodge rhythm is roughly once per second during horde fights."},{"t":"combat","f":"Each melee weapon has at least two attack sequences (light chain and heavy chain). Each attack in a sequence has distinct properties: attack speed, damage, cleave, stagger cleave, base damage, and armor damage \u2014 meaning specific attacks within a chain are better for horde clear vs single-target DPS."},{"t":"combat","f":"Weapons have distinct horde-clear combos and anti-armor combos. Example: Rapier horde-clear = spam lights, anti-armor = spam heavies. Elven Spear horde-clear = push-attack \u2192 light \u2192 light, or heavy \u2192 light \u2192 light."},{"t":"combat","f":"Attacks have a cleave stat that determines how many enemies a swing passes through and staggers. When hordes are dense and attacks can't cleave enough enemies to stagger them all, pushes and push-attacks are used to create space and interrupt incoming hits."},{"t":"combat","f":"Stagger cleave is a separate stat from damage cleave \u2014 an attack can stagger more enemies than it damages. Higher stagger cleave values mean more enemies are interrupted per swing, which is critical for horde survival."},{"t":"combat","f":"The core melee combat loop layers three systems: maintain dodge rhythm (~1/sec), execute the correct weapon combo for the situation (horde-clear or anti-armor), and use push-attacks when enemy density overwhelms cleave \u2014 all simultaneously."},{"t":"combat","f":"Hit stop freezes both attacker and victim animations for a few milliseconds on hit impact, implemented by setting character's custom time dilation to 0, then restoring to 1 after a duration via timer."},{"t":"combat","f":"Hit stop and hit stun are different: hit stun only affects the victim and disallows blocking so the attacker can connect combos, while hit stop affects both attacker and victim as a visual/feel effect."},{"t":"combat","f":"Hit stop duration should be set per-attack using a data asset with explicit values for each move (damage, hit stop duration) rather than a single global value, giving designers precise control per combo hit."},{"t":"combat","f":"During hit stop, the victim's sprite/visual mesh should shake (flip-flop left/right) but the hitbox must NOT move with it \u2014 only the visual representation shakes to maintain consistent hit detection."},{"t":"combat","f":"Setting time dilation to 0 does NOT stop the actor from ticking, so tick functions and subroutines can still run during hit stop to drive effects like sprite shaking."},{"t":"combat","f":"Stronger hit stop leaves the attacker vulnerable in multiplayer (3+ players), so hit stop duration must be balanced against gameplay risk \u2014 Sakurai noted this tradeoff in Smash Bros design."},{"t":"combat","f":"Enemy basic setup requires: animations, a hitbox, health, and the ability to be hit by the player's attacks as the minimum foundation."},{"t":"combat","f":"Enemy states start with two basics: idle and pursuing. In idle, a distance radius check triggers pursuit; in pursuing, the enemy's movement direction vector always angles toward the player."},{"t":"combat","f":"Line of sight (LOS) is calculated by tracing the line between enemy and player positions and iteratively performing small circular collision queries for obstacles along that line; LOS true means clear path, LOS false means blocked."},{"t":"combat","f":"Enemy attack gating: the enemy must pass both a distance radius check AND a line-of-sight check before transitioning from idle to attack/pursue state, preventing attacks through walls."},{"t":"combat","f":"When LOS is lost during pursuit, the enemy reverts to idle state to prevent getting stuck on or phasing through obstacles, but a tile-tracking pathfinding system can maintain pursuit around corners."},{"t":"combat","f":"Hitboxes in Smash Bros style games use sphere colliders rather than cube/cuboid colliders, as spheres are more authentic to the original Smash Bros hit detection system."},{"t":"combat","f":"Hitboxes should be spawned as separate actors/objects that self-destroy after a short lifetime, not permanently attached colliders \u2014 they are instantiated on attack, check collision, apply damage, then auto-despawn."},{"t":"combat","f":"Hitboxes must filter by owner/team so the attacking player does not damage themselves \u2014 collision checks should exclude the player who spawned the hitbox."},{"t":"combat","f":"Hitbox spawn position must account for the character's facing direction \u2014 spawning always to one side regardless of facing is a common bug that requires reading the character's current orientation to offset correctly."},{"t":"combat","f":"Hitboxes and hurtboxes are distinct concepts: hitboxes are offensive collision zones spawned during attacks, while hurtboxes are defensive zones on the character body that receive damage \u2014 they should be implemented as separate systems."},{"t":"combat","f":"Advanced hitboxes can detect where on the weapon collision occurred (e.g. center of sword vs tip of boxing glove) to vary damage or knockback based on hit position \u2014 this is a refinement on basic collision checking."},{"t":"combat","f":"Hit stop (freezing time momentarily on impact) should escalate across a combo chain \u2014 small pause on hit 1, medium on hit 2, large on hit 3 \u2014 to sell the weight of the final hit"},{"t":"combat","f":"Knockback should trigger on the final hit of a combo to physically displace the enemy, reinforcing the heavy impact already sold by hit stop"},{"t":"combat","f":"Hit flash (briefly changing enemy color/material to white on damage) provides immediate visual feedback that a hit connected before any animation plays"},{"t":"combat","f":"Weapon swing and impact sounds should reuse a single sound cue but randomize pitch between a min and max value each play to avoid repetition"},{"t":"combat","f":"Impact VFX (blood splatter, sparks, explosion) must spawn at the exact point of contact between weapon and enemy to sell the hit location"},{"t":"health","f":"Health bars should animate smoothly (lerp/tween) when losing HP rather than instantly jumping, so the player can perceive the exact amount of damage dealt"},{"t":"dialogue","f":"A dialogue system can be built with three core scripts: a DialogLine script (serialized data class holding text, character name, portrait, and event triggers), a DialogueActivator script (holds a list of DialogLines and is placed on game objects like NPCs or room triggers to activate cutscenes), and a third controller script that manages playback."},{"t":"dialogue","f":"The DialogLine script is serialized (not attached to a game object) and serves as a data container variable used by other scripts, holding: display text, character name, character portrait, and event triggers for character movement and animations."},{"t":"dialogue","f":"The DialogueActivator script is placed on in-scene game objects (NPCs, room regions) to both store an ordered list of DialogLine instances and serve as the trigger/entry point for initiating a cutscene sequence."},{"t":"dialogue","f":"Dialogue UI layout uses three key screen regions: a dialogue text box at the bottom, character portrait panels for showing expressions, and the remaining upper screen area reserved for in-scene action/movement during the conversation."},{"t":"dialogue","f":"DialogLine events can trigger in-scene actions such as character movement and animation changes during dialogue playback, allowing cutscenes to combine text display with choreographed scene actions."},{"t":"dialogue","f":"Character portraits support multiple expressions that can change per dialogue line, allowing NPCs to display different emotional states during a conversation sequence."},{"t":"dialogue","f":"Dialog IDs are automatically read from the name of the dialog graph object created in Unity, but can be manually edited to any desired value."},{"t":"dialogue","f":"C-vars (conversation variables) are defined in the dialog graph as a scratch pad to control conversation flow, allowing fine-tuning of what the player can see based on c-var values. They are referenced by name across all graph nodes."},{"t":"dialogue","f":"The dialog XML structure uses a start_statement node as the entry point, with statement IDs linking statements to responses. Statements contain NPC text, responses contain player reply options."},{"t":"dialogue","f":"Dialogs are exported from a Unity-based dialog graph editor to a dialogs.xml file, with optional localization export that replaces inline text with hash-based localization keys prefixed by the dialog ID and an underscore."},{"t":"dialogue","f":"The NPC ID in the mod's empty-handed template points to a dialog ID, creating the link between an NPC entity and its conversation tree. The dialog entry in dialogs.xml must match this NPC reference."},{"t":"dialogue","f":"Dialogs can be hot-reloaded at runtime using a console command (e.g. 'dialogue') that rereads all dialog XML files from the mods folder without restarting the game."},{"t":"dialogue","f":"An NPC conversation is initiated by adding an 'NPC Conversation' component to a GameObject in the hierarchy, which is required to start any conversation with that character."},{"t":"dialogue","f":"Dialogue trees are built with speech nodes that contain: character name, dialogue text, icon/sprite, optional audio with volume control, optional TextMeshPro font override, and an optional event callback for quest acceptance or other actions."},{"t":"dialogue","f":"Branch conditions are created via option nodes that present the player with selectable responses (e.g., 'I want a quest please' vs 'go away'), where each option can lead to further speech nodes or end the conversation if left unconnected."},{"t":"dialogue","f":"Quest triggers are handled by adding Unity events to speech or option nodes, allowing actions like quest acceptance to fire at specific points in the conversation flow."},{"t":"dialogue","f":"Default dialogue settings (default sprite, default TextMeshPro font, continue/end button fonts) are configured by clicking on empty space in the Dialogue Editor window, applying to all nodes unless overridden per-node."},{"t":"dialogue","f":"Dialogue conversations should be edited on GameObjects in the scene hierarchy rather than on prefabs, as editing prefab-based conversations may fail to save the dialogue data properly."},{"t":"dialogue","f":"DialogLine extends Resource and has properties: text, time_between_letters (character processing delay), and read_time (delay until next line)"},{"t":"dialogue","f":"Dialogue resource has a name/ID field and an array of DialogLine resources"},{"t":"dialogue","f":"Each NPC has a DialogueManager node that contains an array of Dialogue resources"},{"t":"dialogue","f":"NPC interaction is triggered by pressing the E key, which displays dialogue text on screen"},{"t":"dialogue","f":"Dialogues are created via Godot's custom resource system: New Resource > Dialogue, then managed under NPC Dialogues in the inspector"},{"t":"dialogue","f":"The dialogue system is designed to be project-portable \u2014 it can be dropped into any new Godot project and work standalone"},{"t":"NPC dialogue trigger","f":"NPC dialogue is triggered by proximity detection using a sphere collider centered on the NPC with mesh renderer removed and isTrigger enabled, allowing the player to walk through it"},{"t":"dialogue trigger condition","f":"Player detection uses OnTriggerEnter to set a boolean playerDetection=true when the collider name matches 'Player', and OnTriggerExit to set it back to false"},{"t":"dialogue input condition","f":"In Update(), the system checks if playerDetection is true AND the player presses the F key to start the dialogue interaction"},{"t":"NPC conversation variable","f":"A boolean variable called playerDetection serves as the state flag that gates whether NPC dialogue can be initiated, toggled by trigger enter/exit events"},{"t":"dialogue","f":"Typewriter-style dialogue systems that require player input (e.g., pressing A) between each line create unnecessary interaction friction; auto-advancing dialogue where characters keep talking without button prompts creates conversational fluidity."},{"t":"dialogue","f":"Branching dialogue trees grow exponentially when NPCs use open-ended or polite phrasing (e.g., 'Could we sit down and speak?') because each optional action requires writing a refusal branch; replacing with direct/authoritative NPC lines (e.g., 'You're under arrest') eliminates entire branch paths."},{"t":"dialogue","f":"Dialogue branch conditions should only exist when the player choice adds meaningful narrative value; if a branch (e.g., 'I don't want to sit down') doesn't change outcomes or add story content, it should be eliminated entirely rather than written out."},{"t":"dialogue","f":"Cinematic editing principles (cutting meals, bathroom breaks, pleasantries) can be applied to game dialogue by reducing NPC conversations to only the essential lines that drive the scene forward, skipping realistic but non-functional exchanges."},{"t":"dialogue","f":"NPC conversation triggers should force the scene state directly (e.g., putting the player on the floor) rather than requesting cooperation, because forced state transitions eliminate the need for response-branch conditions handling player refusal."},{"t":"dialogue","f":"Early dialogue scripts tend to be overwritten with realistic conversational filler; iterative reduction passes that ask 'what are the basic things that have to be said' produce tighter, more effective dialogue trees with fewer branches and variables to track."},{"t":"inventory","f":"Inventory system populates slots as items are collected; clicking a slot displays item info, clicking again uses the item (e.g., heal); right-click drops items which respawn on the map."},{"t":"inventory","f":"Inventory UI is designed to be minimalistic and semi-transparent so gameplay action remains visible behind it, inspired by Hollow Knight."},{"t":"inventory","f":"The inventory system is built as a multi-part series with a planned extension for an equipment system that pairs with the inventory."},{"t":"inventory","f":"Quick slots UI allows dragging items from inventory grid into numbered slots (1-4), pressing number keys selects that tool which then appears in the player's hand for use."},{"t":"inventory","f":"Items can be removed by dragging them into a trash can UI element to delete them, right-clicking consumable items refills player status bars, and hovering shows item info tooltip."},{"t":"inventory","f":"When inventory or any menu is open, player interaction with world items must be disabled \u2014 otherwise players can still select and pick up items while the inventory UI is visible."},{"t":"inventory","f":"Cursor visibility is set to false at game start (in inventory system Start method), toggled to visible when inventory or crafting panel opens, and back to invisible when closed."},{"t":"inventory","f":"Selected world items remain visually selected (highlighted hand icon) when inventory opens if interaction is not disabled, requiring explicit deselection logic on menu open."},{"t":"inventory","f":"Equip system uses drag-and-drop from inventory grid slots into dedicated quick slot UI elements, with the equipped item model appearing in the player character's hand when the corresponding number key is pressed."},{"t":"inventory","f":"Items are implemented as ScriptableObjects (data containers) rather than MonoBehaviours, meaning they persist between playthroughs and don't use Start/Update methods."},{"t":"inventory","f":"A [CreateAssetMenu] attribute is added above the ScriptableObject class so Unity's Create menu gains an 'item scriptable object' option for authoring new items directly in the editor."},{"t":"inventory","f":"Each item ScriptableObject has a public string itemName field that the InventoryManager uses as a dictionary key to identify which item is being clicked or used."},{"t":"inventory","f":"Item stat effects use a public enum StatToChange with values {None, Health, Mana, Stamina}, exposed as a dropdown in the Unity Inspector, paired with a public int amountToChangeStat for the effect magnitude."},{"t":"inventory","f":"A second enum pattern for attributes (Strength, Defense, Intelligence, Agility) can be added alongside StatToChange to let items modify both stats and attributes independently."},{"t":"inventory","f":"Item ScriptableObjects are dragged into the InventoryManager's itemScriptableObject slots on the inventory canvas to register them, building a dictionary of all items that exist in the game."},{"t":"inventory_ui_sorting","f":"Inventory list UI uses clickable column headers (name, value, etc.) to sort items by that column, similar to SkyUI menu system from Skyrim."},{"t":"inventory_template_pattern","f":"A single disabled menu item template GameObject is cloned at runtime for each inventory entry; the template stays disabled so it doesn't render, and copies are instantiated per item in the array."},{"t":"inventory_data_model","f":"Each inventory item type (e.g., weapons) is represented as a ScriptableObject instance in Unity, and an array of these ScriptableObjects is assigned to a manager script via drag-and-drop in the inspector."},{"t":"inventory_item_details","f":"Clicking an item in the scrollable inventory list on the left updates a detail panel on the right showing that item's attributes."},{"t":"inventory_item_attributes","f":"Menu item entries initially only display a name field; value is being added as a second column attribute, with manual spacing used for alignment."},{"t":"inventory","f":"Inventory UI uses a dedicated Canvas with Canvas Scaler set to 'Scale with Screen Size' at reference resolution 1920x1080 to handle multiple resolutions."},{"t":"inventory","f":"Inventory menu panel hierarchy: Canvas > Inventory Menu (panel) > Inventory Slots (panel) + Inventory Description (panel); Inventory Slots contains Item Slot sub-panels (turned into prefabs for duplication); Description contains Item Image and Item Description panels."},{"t":"inventory","f":"Inventory menu uses a semi-transparent black background (alpha ~40) for a Hollow Knight-style minimalist see-through overlay that still shows gameplay behind it."},{"t":"inventory","f":"Inventory menu rect transform uses margins of 150 on left/right sides and 140 on top/bottom to inset the panel from screen edges."},{"t":"inventory","f":"A Horizontal Layout Group component on the Inventory Menu parent controls the left (slots) and right (description) child panels, with padding of 25 on all sides and 'Force Expand' disabled."},{"t":"inventory","f":"The inventory UI layout has slots grid on the left side and a zoomed-in item image with text description on the right side, and the menu is toggled via a button press that also pauses the game."},{"t":"inventory","f":"Inventory grid is configured by specifying slots count, slots per row, and rows per page \u2014 e.g., 80 slots, 4 per row, 5 rows per page creates paginated pages of 5\u00d74 grids"},{"t":"inventory","f":"Slot prefab is 'inventory slot UI' prefab reused across inventory grid, quick access bar, and equipment panel; cell size set via grid layout (e.g., 100x100 for inventory, 65x65 for quick access bar)"},{"t":"inventory","f":"Quick access bar uses a button number text prefab that displays the item quantity for stacked items, with configurable slot count (e.g., 9 slots)"},{"t":"inventory","f":"Equipment panel is created via the inventory system window which auto-adds an equipment component to the player and auto-references each slot's game object"},{"t":"inventory","f":"Save/load functionality requires inventory component, quick access bar component, and equipment component on the player to all reference the same item DB asset"},{"t":"inventory","f":"Currency system supports tiered conversion: copper converts to silver at a set conversion rate, silver converts to gold \u2014 each currency has an icon and a numeric conversion threshold"},{"t":"inventory","f":"Object pickup uses a tag-based system: create a 'can pick up' tag applied to all pickupable objects, then raycast or check against this tag to determine if an object can be picked up."},{"t":"inventory","f":"Held objects are positioned using an empty GameObject called 'hold position' parented under the camera, dragged to the desired hold distance in front of the player."},{"t":"inventory","f":"When picking up an object, its rigidbody is set to kinematic, which prevents physics forces but causes wall clipping; this is solved by rendering the held object on a separate 'hold layer' with a dedicated camera using depth-only clear flags and depth value 1."},{"t":"inventory","f":"The pickup camera settings are: clear flags set to 'Depth Only', culling mask set to only the hold layer, near clipping plane set to 0.01, and depth set to 1; the main camera's culling mask deselects the hold layer."},{"t":"inventory","f":"Object rotation while held uses mouse axes applied directly to the object's rotation, requiring the mouse look/character controller script to be disabled during rotation and re-enabled after to prevent simultaneous camera movement."},{"t":"inventory","f":"The pickup script is attached to the player's camera object and requires two references: a public reference to the player GameObject and a public Transform reference to the hold position."},{"t":"inventory","f":"Inventory system built on ScriptableObjects allows data to persist between scenes as long as each scene contains a reference to the inventory ScriptableObject asset."},{"t":"inventory","f":"Items support drag-and-drop reordering in the UI grid, and the rearranged order persists when the inventory is closed and reopened."},{"t":"inventory","f":"Right-click context menus provide item-specific actions: consumables show 'Eat' and 'Drop', while equipment shows 'Equip' and 'Drop'."},{"t":"inventory","f":"Consumable items like apples have a stack count that decreases on use (eating); when the stack reaches zero the item is removed from the inventory."},{"t":"inventory","f":"Equipping an item removes it from the inventory and moves it to an equipment slot; if a slot is already occupied, the previously equipped item is returned to the inventory with its current durability."},{"t":"inventory","f":"The architecture uses Model-View-Controller (MVC): the Model is the inventory ScriptableObject, the View is the inventory UI, and a Controller separates logic from presentation for maintainability."},{"t":"lighting","f":"Set color space to Linear under Edit > Project Settings > Player for physically accurate lighting calculations"},{"t":"lighting","f":"Set camera render path to Deferred to support advanced lighting features like multiple dynamic lights and better light interaction"},{"t":"lighting","f":"Add a Reflection Probe (right-click in hierarchy) and bake it to capture environment reflections on nearby surfaces"},{"t":"lighting","f":"Use Post Processing stack with ACES tone mapping on the Color Grading effect to achieve accurate, cinematic color response"},{"t":"ambient_occlusion","f":"Amplify Occlusion (free asset) produces better ambient occlusion results than Unity's built-in screen-space ambient occlusion"},{"t":"lighting","f":"Increase directional light intensity to compensate for scene darkening caused by linear color space and ACES tone mapping"},{"t":"lighting","f":"Lumen is UE5's default global illumination method focused on indirect realtime lighting; to use baked lighting instead, set global illumination method to 'None' in both viewport and project settings to disable Lumen"},{"t":"lighting","f":"GPU Lightmass is an experimental UE5 plugin that bakes lights using RTX hardware ray tracing instead of CPU, requiring 'Support Hardware Ray Tracing' and 'Use Hardware Ray Tracing when enabled' both checked in Project Settings"},{"t":"lighting","f":"For baked lighting, all lights (directional, sky, point) must be set to Static or Stationary mobility \u2014 Movable lights cannot be baked"},{"t":"lighting","f":"A lightmap is a texture that stores pre-calculated baked lighting information per static mesh, while Lightmass is the actual renderer/tool that performs the ray tracing calculations to generate those lightmaps"},{"t":"lighting","f":"Virtual Texture Support must be enabled in project settings for GPU Lightmass to function, as it splits the scene's large lightmap into smaller pieces for optimized next-gen rendering"},{"t":"lighting","f":"Disabling real-time viewport rendering (VP Realtime off) during GPU Lightmass baking significantly speeds up the build process"},{"t":"lighting","f":"Cloud shading alone costs 5 milliseconds at 1080p on a 13 teraflop machine, covering only half the frame surface area"},{"t":"lighting","f":"Unreal Engine 5.5 cloud shading runs over 800% slower than Unreal Engine 5.4 and still relies on temporal smear abuse to hide jittering artifacts"},{"t":"lighting","f":"A realistic third-person action game scene is typically 75% static objects and 25% dynamic elements (characters, breakable objects, vehicles, moving light occluders like doors/windows, and togglable light sources)"},{"t":"lighting","f":"PS4 rendered 8th-gen visuals at 1080p 30fps on 1.9 teraflops; doubling frame rate to 60fps requires ~2x power, fitting within PS5 budget with large headroom for 9th-gen visual improvements"},{"t":"lighting","f":"Moving from 1080p to 4K requires 4x computational power, consuming over half the available hardware resources just to maintain baseline visual fidelity"},{"t":"lighting","f":"Moving light occluders (doors, windows) and togglable light sources are classified as dynamic elements requiring realtime lighting solutions rather than baked approaches"},{"t":"lighting","f":"Light mapping UVs must be set up on UV Channel 2 with no overlapping UV islands to prevent light bleeding and pixelation artifacts in baked lightmaps."},{"t":"lighting","f":"Static objects should be marked as static to be included in baked lightmaps, while dynamic/moving objects should not be marked static and should use light probes instead for indirect lighting."},{"t":"lighting","f":"Unity can auto-generate light mapping UVs from existing UV channels, but this often causes issues; manually authored Channel 2 UVs with non-overlapping islands produce cleaner bakes."},{"t":"lighting","f":"PBR material workflow using base color map, emissive map, mask map, and metallic/smoothness maps ensures assets look correct under any lighting scenario including baked and realtime."},{"t":"emissive","f":"Emissive maps are included as part of the standard PBR texture set (base color, emissive, mask/metallic/smoothness) for arch viz models, contributing to both baked and realtime illumination."},{"t":"lighting","f":"Gathering real-world reference images before building a scene helps determine directional light angle, additional light placement, and overall mood for realistic lighting setups."},{"t":"ambient_occlusion","f":"AO maps enhance shadows by adding subtle contact shadows in crevices and cracks, bringing out depth in materials without additional geometry cost."},{"t":"ambient_occlusion","f":"In HDRP, ambient occlusion is not assigned directly to the lit shader but is channel-packed into the mask map, stored in a specific color channel of a single RGBA texture alongside metallic and roughness maps."},{"t":"lighting","f":"Normal maps simulate bumps and grooves by altering how light interacts with the surface without increasing geometry; in HDRP the texture type must be set to 'normal map' in import settings."},{"t":"lighting","f":"Height maps displace actual surface geometry (unlike normal maps which only simulate it) and require the HDRP Lit shader's displacement mode set to 'Tessellation Displacement' with tessellation mode set to 'Full'."},{"t":"lighting","f":"HDRP channel-packed mask map stores four grayscale maps (metallic, AO, detail mask, smoothness) in RGBA channels of a single texture, allowing the renderer to sample all four with a single texture fetch."},{"t":"lighting","f":"When importing textures for HDRP materials, set texture type to 'default' (except normal maps) and disable sRGB for grayscale maps like metallic, smoothness, and AO to ensure correct linear-space interpretation."},{"t":"networking","f":"ClientNetworkTransform overrides NetworkTransform with IsServerAuthoritative returning false, allowing client-controlled movement without server round-trip for snappy response, while still implementing server reconciliation for 100% server authority"},{"t":"networking","f":"Unity Netcode for GameObjects v1.4 requires NetworkManager component with Unity Transport set to localhost, and each player prefab needs a NetworkObject component plus NetworkTransform for sync"},{"t":"networking","f":"NetworkManager.Singleton.StartHost() or StartClient() are the entry points for multiplayer sessions, with host combining server and client in one instance"},{"t":"networking","f":"Syncing rigid bodies between server and clients is the core challenge of networked physics; client-side prediction avoids round-trip latency while server reconciliation corrects drift"},{"t":"networking","f":"ClientNetworkTransform syncs position and rotation but scale sync can be disabled to reduce unnecessary network traffic"},{"t":"networking","f":"Two main multiplayer architectures: dedicated servers (server-authoritative, harder to cheat, more costly) vs peer-to-peer (one player hosts as both server and client, cheaper but easier to cheat)"},{"t":"networking","f":"Server-authoritative model: server moves all players and handles all logic while clients only send input. Alternative: each client moves their own character and position is synchronized, giving smoother gameplay but easier to cheat."},{"t":"networking","f":"Unity's default NetworkTransform is server-authoritative (only server can move it). To allow client-authoritative movement, create a custom ClientNetworkTransform script that overrides the OnIsServerAuthoritative method to return false."},{"t":"networking","f":"NetworkTransform sync settings: only check the variables you want to sync (position axes, rotation axes, scale) to avoid sending unnecessary data and reduce bandwidth/latency."},{"t":"networking","f":"NetworkVariable with configurable read/write permissions can represent synced game state like player health. Scripts must extend NetworkBehaviour (not MonoBehaviour) and use OnNetworkSpawn instead of Start for initialization."},{"t":"networking","f":"Ownership check pattern: in OnNetworkSpawn, check IsOwner to deactivate extra cameras for non-owned players. In Update, gate movement input behind IsOwner so clients only control their own character."},{"t":"client-side prediction","f":"Client-side prediction uses the same shared movement processing code as the server, feeding it the entity's current state and the player's input to compute the predicted position locally without waiting for the server response."},{"t":"server reconciliation","f":"Reconciliation compares the client's predicted position against the server's authoritative state; if they match (e.g., both at 1,0), the prediction is accepted, otherwise the client must accept the authoritative state and resolve the misprediction."},{"t":"tick accumulation during latency","f":"Multiple movement ticks occur between sending input and receiving the server's state response (e.g., client advances from 1,0 to 2,0 to 3,0 while waiting), causing the client's current position to diverge from the authoritative state which only reflects tick 1."},{"t":"state history for reconciliation","f":"The client needs a programmatic way to map a past local state to the corresponding server tick \u2014 e.g., knowing that the local position of 1,0 at tick N corresponds to the server's authoritative state for that same tick \u2014 requiring a history buffer of past predicted states."},{"t":"deterministic simulation","f":"Prediction accuracy depends on both client and server starting from the same state (e.g., both at 0,0) and using identical movement logic with the same input, guaranteeing deterministic outcomes like both arriving at 1,0."},{"t":"input-to-state pipeline","f":"Without client prediction, pressing a key (e.g., D to move right) sends input to the server and the client must wait for the full round-trip before rendering any movement, creating perceived input lag equal to the network latency."},{"t":"networking","f":"Authoritative server architecture means all game logic and calculations run on a central server; clients only send inputs while the server manages the entire game state, preventing hacked clients from modifying values like health or position"},{"t":"networking","f":"The server update loop follows a three-step cycle: clients send actions to the server, the server updates the game state periodically (tick), then sends the new game state back to all clients"},{"t":"networking","f":"UDP is preferred over TCP for fast-paced multiplayer because TCP has significant per-packet overhead and causes head-of-line blocking, which is brutal for FPS multiplayer experience"},{"t":"networking","f":"Delta compression and optimized serialization strategies are used to squeeze maximum information into the smallest number of bits, critical for scaling to 50-100 players on a single server"},{"t":"networking","f":"Without client-side prediction, a round-trip latency of ~200ms creates a perceivable delay between player input and character movement; at 500ms the game becomes unplayable"},{"t":"networking","f":"Client-side prediction, snapshot interpolation, and lag compensation are the three core techniques that solve input-to-response latency in authoritative multiplayer games"},{"t":"networking","f":"For fast-moving multiplayer objects, custom extrapolation outperforms Unity's built-in NetworkTransform, NetworkRigidBody, and interpolation \u2014 it reaches endpoints faster with less visible delay and stays more in sync across clients."},{"t":"networking","f":"Client-authoritative movement pattern in FixedUpdate: if owner, process local input/movement then send position and velocity to server via RPC; if not owner, extrapolate from previous position+velocity data (or snap without interpolation)."},{"t":"networking","f":"Without interpolation (raw snapping), networked objects appear bouncy and jerk around; NetworkTransform with interpolation is smoother but introduces noticeable positional delay that worsens significantly under poor network conditions (e.g., 2.5G simulation)."},{"t":"networking","f":"The server acts as a relay in client-authoritative movement: client sends position and velocity to the server, which forwards that data to all other clients for extrapolation."},{"t":"networking","f":"Local movement uses transform rotation from horizontal axis input and sets rigidbody velocity directly on the authoritative client, keeping physics-based movement simple for network replication."},{"t":"networking","f":"NetworkRigidBody synchronization mostly matches NetworkTransform quality but both lag behind custom extrapolation; the rigidbody on the prefab must NOT be set to kinematic for physics-based networked movement."},{"t":"lag_compensation","f":"Server receives a shot packet, reads the latency on that packet, factors in interpolation, infers the exact tick the client fired, rewinds game state to that tick, and checks player positions at that historical time to determine if the shot was a hit."},{"t":"interpolation","f":"The client does not render a player at their latest known position; instead it holds off by one tick and smoothly animates the player between the last two known positions. On a 64-tick matchmaking server, ticks arrive every ~16ms, so interpolation adds one tick (~16ms) of visual delay."},{"t":"latency_budget","f":"Total visual delay without lag compensation = (enemy_ping / 2) for enemy's action to reach server + (my_ping / 2) for server to send to me + 1 tick for interpolation + (my_ping / 2) for my shot to reach server. Each half-ping and interp tick compounds the positional discrepancy."},{"t":"peeker_disadvantage","f":"With lag compensation, you can be hit after going around a corner on your screen because the shooting player's client saw you in the open for the duration of your peek \u2014 the entire peek just occurred after a delay (ping + interp) on the shooter's screen."},{"t":"hit_priority","f":"Lag compensation does NOT determine who shot first; the first shot packet to arrive at the server is the one that registers first, giving the lower-ping player an advantage in simultaneous engagements."},{"t":"tick_rate","f":"A standard matchmaking server runs at 64 ticks per second (~16ms per tick). Without interpolation, player positions would visually jump between discrete tick positions, and since GPU refresh rate, monitor refresh rate, and server tick rate are not synchronized, motion appears unsmooth."},{"t":"client-side prediction","f":"Client-side prediction works by moving the player locally while waiting for server response, hiding latency in authoritative server architecture. The client sends inputs to the server, moves the player locally using the same movement logic, stores the resulting position in a state buffer, then reconciles when the server response arrives."},{"t":"server reconciliation","f":"Server reconciliation checks if the client's predicted position in the past matches the server's authoritative snapshot for that same tick. When the client receives the server state, it sets rigidbody.position to the server's position and replays any inputs that occurred after that tick."},{"t":"tick-based input buffering","f":"Both client state and input history are stored in circular buffers of size 1024, indexed by tick number. Each InputMessage contains a uint tick and an Inputs struct. Each ClientState contains a uint tick, Vector3 position, and Vector3 velocity. The buffer size (1024) defines how far back reconciliation can reach."},{"t":"client prediction loop","f":"In FixedUpdate: (1) capture current input via SetInput(), (2) create InputMessage with current tick number and input, (3) send InputMessage to server, (4) move the player locally using the input, (5) call Physics.Simulate(Time.fixedDeltaTime), (6) store resulting position in clientStateBuffer at current tick, (7) increment tick number. Moving the player BEFORE storing in the buffer is critical."},{"t":"server authoritative processing","f":"On the server when receiving an InputMessage: (1) move the player using the received input, (2) call Physics.Simulate(), (3) create a StateMessage containing rigidbody.position, rotation, velocity, angularVelocity, and set stateMessage.tick = inputMessage.tick, (4) send the StateMessage back to the client. The server echoes back the tick number so the client knows which prediction to compare against."},{"t":"physics simulation in netcode","f":"Both client and server call Physics.Simulate(Time.fixedDeltaTime) manually after applying player movement each tick, ensuring deterministic physics stepping that is synchronized between client prediction and server processing. This manual simulation call is essential for prediction and reconciliation to produce matching results."},{"t":"networking","f":"Unity Relay enables multiplayer connections without dedicated servers, port forwarding, or firewall configuration by routing traffic through Unity's relay servers using a join code system."},{"t":"networking","f":"Unity Relay setup requires only three lines of code for basic functionality: allocate a relay, get a join code, and have clients join with that code."},{"t":"networking","f":"Unity Relay, Lobby, and Netcode for Game Objects are three independent but interoperable tools \u2014 Lobby can automatically share relay join codes so players don't need to manually exchange them."},{"t":"networking","f":"Without a relay or port forwarding solution, peer-to-peer multiplayer only works on the same local machine or LAN \u2014 remote players are blocked by firewalls and NAT."},{"t":"networking","f":"Destructible voxel objects can be synchronized across network in multiplayer by tracking per-voxel health state and replicating damage events to all clients."},{"t":"networking","f":"Voxel health can be visually indicated by color interpolation (e.g., shifting toward red as health decreases), with this visual state derived from replicated health values rather than syncing color separately."},{"t":"networking","f":"A host-or-join server architecture (client-hosted/listen server model) allows one player to act as both server and client, reducing infrastructure needs for prototypes."},{"t":"networking","f":"Synchronizing destructible environments in multiplayer requires replicating both the destruction events (e.g., cannonball impacts) and the resulting state changes (voxel health/removal) to maintain consistency across clients."},{"t":"networking","f":"An authoritative server acts as the sole source of truth for game state, making final calls on events like scoring or boundary checks, overriding any client-side calculations that may differ due to lag or slow hardware."},{"t":"networking","f":"Client-authoritative architecture lets the client report its own actions (e.g. hit registration, position) directly to the server, which accepts them without independent verification \u2014 reducing server computation but exposing the game to cheating and exploits as the player base grows."},{"t":"networking","f":"A hybrid authority model exists where some game events are server-authoritative (e.g. match timing, player count, foul detection) while others are client-authoritative (e.g. player movement or action reporting), balancing development simplicity against cheat resistance."},{"t":"networking","f":"When a client has lag or runs on slow hardware, its local calculations can diverge from the true game state, requiring the server to override the client's version of events to maintain consistency across all players."},{"t":"particles","f":"Spawn rate of 20 particles per second with particle lifetime randomized between 1.2 and 1.6 seconds produces good stylized smoke density in Niagara."},{"t":"particles","f":"For mesh-based smoke VFX, use a mesh renderer instead of sprite renderer to emit custom 3D cloud meshes built from joined ico spheres."},{"t":"particles","f":"Velocity set to cone mode at ~800 units with cone axis (0, 0, 1) makes smoke rise upward; cone angle controls horizontal spread."},{"t":"particles","f":"Initial particle scale randomized between 1.0 and 2.0 adds size variation to smoke puffs for a more natural look."},{"t":"particles","f":"Shape Location module set to cylinder with zero height and radius of 20 offsets spawn positions so particles don't all emit from a single point."},{"t":"particles","f":"Custom smoke mesh workflow: create 3-4 ico spheres (subdivision 1) in Blender, join with Ctrl+J, remesh at voxel size 0.5 with smooth shading, then decimate with un-subdivide to lower poly count."},{"t":"particles","f":"To create a circuit effect in UE Niagara, start with the default Fountain preset and delete all forces, velocity, and location modules to strip it to basics"},{"t":"particles","f":"Set spawn rate to 100 and particle lifetime to a constant value of 5 for steady circuit particle emission"},{"t":"particles","f":"Curl noise force is added to circuit particles after stripping default forces to create organic flowing circuit-like movement patterns"},{"t":"particles","f":"In Niagara, setting lifetime to constant (e.g. 5) rather than a random range gives predictable particle behavior needed for structured effects like circuits"},{"t":"particles","f":"Particle effects can be controlled via user parameters (widgets) that expose spawn rate, drag, color, and opacity as editable values, allowing real-time tweaking without modifying the underlying particle system directly."},{"t":"particles","f":"Spawn rate can be exposed as a user parameter and dynamically increased or decreased at runtime to change particle density and visual intensity."},{"t":"particles","f":"Drag can be increased or decreased via user parameters to control how quickly particles decelerate, dramatically changing the visual look of the same base effect."},{"t":"particles","f":"A modular particle system architecture connects module settings (color, opacity, spawn rate, drag) to user parameters, enabling widget-based control over the entire effect."},{"t":"performance","f":"Static batching combines multiple static meshes into a single mesh and single draw call, reducing CPU-to-GPU draw call overhead automatically for geometry that never moves."},{"t":"performance","f":"A draw call is the CPU telling the GPU to render something; both CPU throughput for issuing calls and GPU capacity for processing them are limited, making excessive draw calls a bottleneck especially on lower-end and mobile devices."},{"t":"performance","f":"Two non-batched cubes plus a background produce 3 separate draw calls (one per object); marking both cubes as batching static reduces this by combining them into a single batch."},{"t":"performance","f":"Objects must be marked as 'batching static' in the Unity inspector to enable static batching; a runtime API also exists for procedural generation scenarios."},{"t":"performance","f":"Unity's Frame Debugger (Window > Analysis > Profiler > Rendering > Frame Debugger) allows inspecting each individual draw call batch sent to the GPU and viewing the scene state between batches."},{"t":"performance","f":"Unity has built-in occlusion culling that prevents rendering objects hidden behind other objects, significantly improving FPS in scenes with many objects"},{"t":"performance","f":"To enable occlusion culling in Unity: enable it on the Camera component, then open Window > Rendering > Occlusion Culling, select static objects with MeshRenderer, check Occluder and Occludee boxes, and press Bake"},{"t":"performance","f":"Unity occlusion culling only works on static objects that do not move; objects must have a MeshRenderer component and be marked as both Occluder (blocks visibility) and Occludee (can be hidden)"},{"t":"performance","f":"Unity's occlusion culling requires a bake step that precomputes visibility cells, and results can be verified using the Visualization tab in the Occlusion Culling window"},{"t":"performance","f":"Without occlusion culling, rendering all visible and hidden objects simultaneously causes FPS to drop progressively as the camera views denser areas of the scene"},{"t":"performance","f":"Each draw call is created per mesh per material \u2014 3 meshes with 2 materials = 6 draw calls; reducing from 1.6M batches to 20K by joining meshes in Blender (Ctrl+J) boosted FPS from 0.5 to ~80"},{"t":"performance","f":"Reducing materials per object from 3 to 1 (using a single texture atlas to color different parts) improved FPS from ~80 to ~180 on a 5000-building scene"},{"t":"performance","f":"Static batching in Unity combines same-material meshes into a single mesh at build time \u2014 enabled by ticking the 'static' checkbox on non-moving objects, boosting FPS from ~180 to ~210"},{"t":"performance","f":"GPU instancing renders multiple copies of the same mesh+material in a single draw call and is enabled via a checkbox on the material \u2014 it achieved the same ~210 FPS as static batching while allowing objects to move"},{"t":"performance","f":"Mesh combining only improves performance when the combined sub-meshes share the same material; joining meshes with different materials still produces one draw call per material"},{"t":"performance","f":"Unity's 'Stats' panel in play mode shows real-time batch count (visible as 'Batches' in top-right stats overlay), which directly corresponds to draw call volume"},{"t":"performance","f":"Occlusion culling in Unity only works on objects marked as static; you bake it via the Render dropdown and it culls objects not visible to the camera, yielding a small frame rate increase (roughly 70\u219273 FPS in a mobile-target scene)."},{"t":"performance","f":"Large single-mesh objects like a water plane cannot be occlusion-culled effectively; splitting them into smaller pieces is required for the occlusion system to cull individual segments."},{"t":"performance","f":"Non-static objects (e.g., trees) are always loaded regardless of camera view; marking them as static enables occlusion culling and reduces rendered vertices from ~1.5M down to ~800K depending on camera angle."},{"t":"performance","f":"Reflection probes set to real-time with HDR on and 256 resolution are costly; switching to individual faces, lowering resolution to 32, and disabling HDR recovers a few FPS."},{"t":"performance","f":"Post-processing effects ambient occlusion and color grading are among the most expensive screen-space effects; disabling just those two boosted FPS from ~79 to nearly 100."},{"t":"performance","f":"Completely disabling the post-processing stack yields the maximum frame rate gain, significantly beyond the ~100 FPS achieved by only turning off ambient occlusion and color grading."},{"t":"frustum_culling","f":"Unity's built-in occlusion culling only disables the MeshRenderer component on static objects, leaving all other components (scripts, colliders, audio, lights, particles) still active and consuming CPU cycles."},{"t":"frustum_culling","f":"Custom frustum culling works by placing edge points (bounding markers) built from the mesh data as child objects of the target GameObject, then testing whether those edge points fall within the camera's frustum to determine visibility."},{"t":"frustum_culling","f":"The frustum culling script must be attached to the same GameObject that holds the MeshRenderer component, not a parent or child, for the edge/bounds calculation to work correctly."},{"t":"frustum_culling","f":"A two-part architecture is used: a single FrustumCullingManager (with auto-catch or runtime camera reference) and per-object FrustumCullingObject components, enabling centralized camera frustum checks against distributed object bounds."},{"t":"frustum_culling","f":"Non-rendering components like point lights and interactable objects benefit significantly from full GameObject disabling via frustum culling, since Unity's default culling only targets mesh rendering and leaves lights, scripts, and physics active."},{"t":"frustum_culling","f":"Objects are re-enabled before they fully enter the camera's field of view (using the edge bounding points), ensuring visually seamless transitions with no visible pop-in regardless of camera rotation speed."},{"t":"performance","f":"Hierarchical LOD (HLOD) reduced draw calls from ~3000-4000 down to 161 by automatically combining child meshes into larger batched groups at distance"},{"t":"performance","f":"Even with static batching saving 11,000 batches, the scene still had 5,900 draw calls and 15,000 batch draw calls, showing static batching alone is insufficient for large modular scenes"},{"t":"performance","f":"HLOD works by subdividing child objects by a configurable chunk size, combining all meshes within each quadrant, and progressively merging into larger quadrants at greater camera distances"},{"t":"performance","f":"Standard LOD groups may not improve performance enough for wide sweeping views with large numbers of distant objects; HLOD applies LOD logic to groups of objects rather than individual meshes"},{"t":"performance","f":"HLOD provides vast performance benefits for large scenes with distant objects but only mediocre improvements in close-quarters environments like city centers where large object groups cannot be replaced with combined meshes"},{"t":"performance","f":"HLOD uses a screen-space projected AABB threshold (e.g., 30% of screen) to determine when to switch between high-quality original meshes and lower-quality combined HLOD meshes"},{"t":"performance","f":"The SRP Batcher reduces CPU time by batching objects that use the same Shader variant, regardless of different materials. Objects with different Shader variants cause separate batches."},{"t":"performance","f":"In URP, the SRP Batcher is enabled by default under Project Settings > Graphics > Render Pipeline Asset inspector, in the Rendering section. If the checkbox is hidden, set Advanced Properties to 'all visible' in Preferences > Graphics."},{"t":"performance","f":"The Frame Debugger (Window > Analysis > Frame Debugger) shows batch causes, draw call counts per batch, and which meshes are included in each batch, enabling direct inspection of draw call batching behavior."},{"t":"performance","f":"GPU instancing and static batching are separate optimization techniques from the SRP Batcher; all three reduce draw calls but work differently. Dynamic batching is also available as a separate toggle on the render pipeline asset."},{"t":"performance","f":"When objects use the same Shader variant (e.g., URP Lit), they batch into a single batch with combined draw calls. A single object with a different Shader (e.g., URP Unlit) forces a separate batch with its own draw call."},{"t":"performance","f":"GPU Resident Draw uses the BatchRendererGroup API to automatically draw game objects with GPU instancing, reducing draw calls and freeing CPU processing time. Works on all platforms including mobile."},{"t":"performance","f":"Enabling GPU Resident Draw instance drawing reduced batches from 4,800 to 2,000 (reduction of ~1,000 batches in a specific view) and increased FPS by an average of ~20 FPS in Unity's Fantasy Kingdom demo."},{"t":"performance","f":"GPU Resident Draw requires Forward+ rendering path to work efficiently. Enable via Edit > Project Settings > Quality > Render Pipeline Asset > Rendering tab, then set rendering path to Forward+ on the associated renderer."},{"t":"performance","f":"GPU Resident Draw increases build times because Unity compiles all BatchRendererGroup shader variants into the build."},{"t":"performance","f":"Disable legacy Static Batching (Edit > Project Settings > Player > Other Settings) when using GPU Resident Draw, as the old static batching system can conflict and reducing it can yield additional performance savings."},{"t":"performance","f":"GPU Occlusion Culling works hand-in-hand with GPU Resident Draw. Additionally, using fixed lightmap size and disabling mipmap limits can further optimize GPU memory when combined with GPU Resident Draw."},{"t":"procedural","f":"Simplex noise is used to generate the noise value for each tile in a chunk, producing a random generated world made out of different blocks."},{"t":"procedural","f":"Chunks are serialized to files storing the Simplex noise value per tile, enabling read/write of player changes for persistent world saves."},{"t":"procedural","f":"The terrain is chunk-based with each chunk containing tiles whose block type is determined by their Simplex noise value, supporting multiple block varieties."},{"t":"procedural","f":"Back-face culling optimization for voxel terrain: check each block's six neighbors, and remove any face shared between two adjacent solid blocks. Only surface-exposed faces are rendered, dramatically reducing face count."},{"t":"procedural","f":"Biome generation was replicated using Henrik Nyberg's Minecraft terrain generation method, which uses noise-based heightmaps but has optimization limitations since it is not the actual Minecraft source code."},{"t":"procedural","f":"Voxel blocks use per-face textures applied via decals/extras on each of the six faces, allowing different textures per side (e.g., grass top, dirt sides) and enabling individual face removal for culling."},{"t":"procedural","f":"Texture resolution mismatch causes blurriness: low-resolution texture pack images mapped onto higher-resolution block faces produce a blurry effect; textures must match the target block's UV scale."},{"t":"procedural","f":"Noise generators are used for top-down world generation where each location gets a noise value and tiles spawn based on the range that the noise gives for that location"},{"t":"procedural","f":"Heightmap generator 2D is used for side-scrolling procedural generation like Terraria, while noise generators are used for top-down generation"},{"t":"procedural","f":"Procedural generation pipeline in Godot 4 requires three components: a generator (noise or walker), a renderer (TileMap Gia Renderer), and a TileMap node"},{"t":"procedural","f":"Walker generator produces rogue-like dungeon generation, while noise generator produces open-world random terrain generation"},{"t":"threejs","f":"Three.js LOD (Level of Detail) class allows switching mesh detail levels based on camera distance. Create with 'const lod = new THREE.LOD()', add meshes via 'lod.addLevel(mesh, distance)' where distance is the threshold in world units."},{"t":"threejs","f":"LOD.addLevel(mesh, distance) takes two arguments: the mesh object and the minimum distance from camera at which that mesh should be displayed. Lower detail meshes should have higher distance values."},{"t":"threejs","f":"LOD.getCurrentLevel() returns the index of the currently active detail level, which can be used in the animation loop to track or display which LOD tier is rendering."},{"t":"threejs","f":"CSS2DRenderer and CSS2DObject can be used to attach HTML/CSS labels to 3D objects in a Three.js scene, enabling HUD-style overlays that track world-space positions."},{"t":"threejs","f":"Performance optimization strategy: create multiple copies of the same model with decreasing triangle/vertex counts, then use THREE.LOD to automatically swap between them based on camera proximity."},{"t":"threejs","f":"AmbientLight is instantiated with color and intensity parameters and added to the scene; it equally brightens everything with constant color, useful for simulating bounce light in shadowed areas."},{"t":"threejs","f":"HemisphereLight takes two colors (sky and ground) and interpolates between them based on surface normal direction \u2014 normals facing up use sky color, normals facing down use ground color."},{"t":"threejs","f":"RectAreaLight is instantiated with color, intensity, width, and height parameters (e.g., width=2.0, height=20.0) to create a soft rectangular light emitting diffuse semi-directional light."},{"t":"threejs","f":"DirectionalLight simulates sunlight with parallel rays from an infinitely far source, uses N\u00b7L (normal dot light) for diffuse calculation, and is the first light type that supports shadow maps."},{"t":"threejs","f":"AmbientLight and HemisphereLight do not support shadows in Three.js; shadow support begins with directional lights which have clear light direction for shadow map calculation."},{"t":"threejs","f":"Three.js is a rendering API that renders to an HTML canvas element within the DOM, not a game engine like Unity or Unreal"},{"t":"threejs","f":"React Three Fiber provides a useful abstraction layer over the raw Three.js API and can accelerate initial learning, though it is not required for production projects"},{"t":"threejs","f":"Custom GLSL shaders are the single biggest differentiator in Three.js scene quality \u2014 mastering vertex and fragment shaders separates basic scenes from professional-grade work"},{"t":"threejs","f":"Blender's Shader Node editor and Geometry Nodes tab teach 3D material and procedural geometry concepts that directly transfer to Three.js scene composition and custom shaders"},{"t":"threejs","f":"Core Blender skills that transfer to Three.js include lighting setup, geometry creation, and PBR material authoring"},{"t":"threejs","f":"InstancedMesh class takes geometry, material, and instance count as constructor arguments, enabling rendering of thousands of objects in a single draw call instead of one render call per object."},{"t":"threejs","f":"All instances in an InstancedMesh must share the same geometry and material, but each instance can have unique geometric transformations (position, rotation, scale) applied via transformation matrices."},{"t":"threejs","f":"Without instancing, rendering N objects requires N separate render calls; with InstancedMesh, even 100,000+ objects can be rendered in a single render call."},{"t":"threejs","f":"To set per-instance transforms, create a temporary Object3D, set its position/rotation/scale, call updateMatrix(), then use instancedMesh.setMatrixAt(index, object3D.matrix) for each instance."},{"t":"threejs","f":"Instancing is ideal for particle systems and repeated environmental objects like grass models covering large terrains, where classic for-loop mesh creation would cause thousands of costly render calls."},{"t":"threejs","f":"Each mesh with a unique material creates one draw call. Two boxes with a physical material = 2 draw calls."},{"t":"threejs","f":"Enabling shadows adds one extra draw call per shadow-casting mesh. Two shadow-casting boxes add 2 extra draw calls (total 4)."},{"t":"threejs","f":"A transmissive material doubles the total draw call count of the entire scene (e.g., 4 draw calls become 8)."},{"t":"threejs","f":"Enabling post-processing (e.g., Bloom) causes the entire scene to be rendered twice, doubling draw calls, plus Bloom itself has a base cost of ~12 draw calls."},{"t":"threejs","f":"Performance should be tracked using stat.js (shows FPS, allocated memory in MB, and ms per frame) or r3f-perf for React Three Fiber (shows polygons, textures, etc.)."},{"t":"threejs","f":"Optimization is about trade-offs: polygon count, materials, textures, shadows, and animations are sliders \u2014 increasing one may require reducing others to maintain performance."},{"t":"webgl","f":"WebGL allows hardware-accelerated 2D and 3D graphics rendering directly in an HTML canvas element using the client's GPU, without external plugins"},{"t":"webgl","f":"The 3D rendering pipeline follows: vertices (x,y,z) -> primitives (triangles) -> lighting/shadows -> rasterization (3D vector to 2D pixel projection)"},{"t":"webgl","f":"Shaders are custom GPU functions that control pixel rendering; vertex shaders process vertex data and fragment shaders calculate per-pixel color, written in GLSL ES (OpenGL ES Shading Language)"},{"t":"webgl","f":"WebGL is based on OpenGL, a graphics library dating back to 1992, and offloads matrix multiplication and linear algebra to the GPU for smooth 60fps rendering"},{"t":"threejs","f":"Three.js abstracts raw WebGL shader writing, allowing developers to build 3D experiences without manually coding vertex and fragment shaders or managing the WebGL context directly"},{"t":"webgl","f":"To initialize WebGL you grab an HTML canvas element from the DOM and call getContext('webgl') to access the rendering API; main logic is JavaScript while shaders use GLSL ES"}];
